constexpr u8 __sAbilityText_2298643350[] = _("电属性招式对地面属性效果绝佳。");
constexpr u8 __sAbilityText_1119614219[] = _("变化招式必定命中。");
constexpr u8 __sAbilityText_138376944[] = _("水属性招式伤害翻倍。");
constexpr u8 __sAbilityText_1288088105[] = _("格斗属性招式伤害翻倍。");
constexpr u8 __sAbilityText_863641131[] = _("拳击与踢击招式伤害1.5倍。");
constexpr u8 __sAbilityText_1051808776[] = _("自身所有招式都视为骨系招式。");
constexpr u8 __sAbilityText_1195032281[] = _("暴击可直接击倒目标。");
constexpr u8 __sAbilityText_2881713990[] = _("音波招式必定击中要害。");
constexpr u8 __sAbilityText_2971655039[] = _("攻击获得+10%的畏缩几率.连续攻\n击招式的每一击单独计算畏缩几\n率.当该宝可梦在场时,剧毒地形的\n回合数不会减少.");
constexpr u8 __sAbilityText_1670749219[] = _("降雨特性会在宝可梦进入战斗时降\n下雨水,持续8回合（携带潮湿岩石\n时为12回合）.雨天使水系招式威\n力提升50%,火系伤害降低50%.部分\n招式和特性在雨天下有特殊效果.\n无法覆盖原始天气.");
constexpr u8 __sAbilityText_3456668370[] = _("该宝可梦每在场完成一个完整的回\n合,其速度在回合结束时提升1级.\n入场的当回合不会触发.");
constexpr u8 __sAbilityText_1952562900[] = _("受到的伤害降低20%（x0.8）,与其\n他减伤效果乘法叠加.此外,免疫击\n中要害,会心一击将作为普通攻击\n处理,并且不会触发攻击要害的效\n果（例如“至骨”的流血效果）.");
constexpr u8 __sAbilityText_1394112613[] = _("当该宝可梦HP全满时,能够承受任\n何一次攻击并至少留下1点HP.此效\n果如同携带了气势披带,因此无法\n抵御连续攻击招式或后续攻击（例\n如“余震”、“雷召”）.");
constexpr u8 __sAbilityText_4174280063[] = _("如果该宝可梦与另一只宝可梦发生\n接触（无论是攻击方还是防御方\n）,对方的属性会变为纯水属性.此\n效果在连续招式或优先度招式命中\n时立即发生,可以在对手的连续攻\n击过程中消除其本系加成.");
constexpr u8 __sAbilityText_1213462467[] = _("该宝可梦受到的所有反伤伤害减\n半；包括具有比例反伤的招式（如\n勇鸟猛攻）、具有撞伤风险的招式\n（如飞膝踢）、或固定反伤的招式\n（如钢炮光线）.麻痹状态无法影\n响该宝可梦,且获得此特性时,若已\n处于麻痹状态则会立刻治愈.");
constexpr u8 __sAbilityText_1769405544[] = _("在沙暴中,对手的命中率变为原来\n的1/1.25,且自身免疫沙暴伤害.会\n被无防御或破格特性识破.");
constexpr u8 __sAbilityText_3764779188[] = _("无论该宝可梦是攻击方还是被攻击\n方,都有几率使对手陷入麻痹.非接\n触攻击有10%几率麻痹,接触攻击有\n30%几率麻痹.");
constexpr u8 __sAbilityText_1123122050[] = _("该宝可梦能够吸收电属性招式,将\n其转化为能量,恢复其最大HP的\n25%.对电属性伤害及其附加效果\n（如电磁波的麻痹）完全免疫.对\n于水/飞行属性宝可梦来说,是消除\n4倍电系弱点的完美选择.");
constexpr u8 __sAbilityText_538609996[] = _("该宝可梦免疫水属性招式,并且受\n到水属性招式攻击时会恢复其最大\nHP的25%.");
constexpr u8 __sAbilityText_643310541[] = _("该宝可梦免疫着迷、惊吓、威吓和\n挑衅.在获得此特性时,如果已经处\n于上述任意状态,则会立刻解除.");
constexpr u8 __sAbilityText_3856252156[] = _("上场时清除所有天气,并且在该宝\n可梦在场期间使所有天气效果（包\n括原始天气）失效.天气仍可以被\n设置,但在该宝可梦下场前,不会提\n供任何伤害加成或触发与天气相关\n的特性.");
constexpr u8 __sAbilityText_3127268423[] = _("该宝可梦的招式命中率变为1.3倍.");
constexpr u8 __sAbilityText_342339123[] = _("防止任何方式陷入睡眠状态,包括\n催眠招式、特性（如哈欠）以及其\n他可能导致睡眠的效果.使用招式\n睡觉将完全失败.若在获得此特性\n前已处于睡眠状态（例如通过烦恼\n种子或特性交换）,则会立刻醒来.\n可被破格等特性识破");
constexpr u8 __sAbilityText_3782056956[] = _("受到伤害前,将自身转变为防御效\n果最佳的纯属性.优先考虑免疫而\n非抗性.每回合仅触发一次.");
constexpr u8 __sAbilityText_3751869641[] = _("防止中毒.所有毒属性伤害减半.与\n其他减伤效果乘法叠加.获得此特\n性时若已中毒,则立刻治愈.");
constexpr u8 __sAbilityText_2458898343[] = _("引火特性使宝可梦完全免疫火属性\n招式.受到火属性攻击后,自身的火\n属性招式威力提升50%,直到下场为\n止.多次被火属性攻击命中不会使\n效果叠加.");
constexpr u8 __sAbilityText_1497801052[] = _("阻挡所有攻击招式的追加效果.免\n疫所有入场陷阱.免疫所有粉末类\n招式,包括催眠粉、麻痹粉、毒\n粉、蘑菇孢子、棉孢子、愤怒粉、\n粉末和魔法粉.");
constexpr u8 __sAbilityText_2295516812[] = _("免疫混乱、威吓和惊吓.获得此特\n性时若已混乱,则立刻解除混乱状\n态.");
constexpr u8 __sAbilityText_2887518319[] = _("防止被招式或红牌强制替换下场.");
constexpr u8 __sAbilityText_3666036191[] = _("进入战斗时,降低所有对手宝可梦\n的攻击1级.");
constexpr u8 __sAbilityText_1435679182[] = _("阻止所有不具有影子游戏特性或非\n幽灵属性的对手替换下场.携带逃\n脱按键或使用替换招式（如快速折\n返）的宝可梦可以逃脱如果在战斗\n中中途替换上场,效果将在下一回\n合生效.");
constexpr u8 __sAbilityText_2340362393[] = _("对使用接触类招式的攻击者造成其\n最大HP1/8的伤害.对于连续攻击招\n式,每次命中都会触发.");
constexpr u8 __sAbilityText_676204920[] = _("只有效果绝佳的招式或间接伤害能\n够伤害到该宝可梦.其他所有直接\n攻击造成的伤害均为零.中毒或特\n性伤害等其他来源的伤害照常生\n效.");
constexpr u8 __sAbilityText_2061226230[] = _("该宝可梦免疫地面属性招式以及其\n他地面效果,如撒菱和场地状态.飞\n行属性招式伤害提升25%.");
constexpr u8 __sAbilityText_901821365[] = _("受到接触类招式攻击时,有30%的几\n率使攻击者陷入睡眠、麻痹或中毒\n状态.状态类型随机选择.");
constexpr u8 __sAbilityText_271579904[] = _("当被施加非瞬间异常状态（睡眠除\n外）时,攻击者也会陷入相同的状\n态.此效果可穿透替身.若该宝可梦\n在被施加异常状态时能够治愈自\n身,则会在治愈前先将异常状态施\n加给攻击者.");
constexpr u8 __sAbilityText_112272438[] = _("免疫所有由招式或特性引起的能力\n降低效果.包括因使用过热等招式\n导致的自身能力降低.");
constexpr u8 __sAbilityText_297626959[] = _("替换下场时,治愈所有异常状态.");
constexpr u8 __sAbilityText_1129620184[] = _("该宝可梦会吸引电属性招式,并对\n其免疫.此外,受到电属性招式攻击\n后,自身最高的攻击能力提升1级.");
constexpr u8 __sAbilityText_533590711[] = _("自身攻击招式的追加效果触发几率\n加倍.");
constexpr u8 __sAbilityText_2157399968[] = _("下雨天气时,速度提升50%.");
constexpr u8 __sAbilityText_3146062719[] = _("大晴天天气时,速度提升50%.");
constexpr u8 __sAbilityText_2792435081[] = _("该宝可梦的招式命中率变为1.2倍.\n攻击命中时,移除目标的幽灵属性.");
constexpr u8 __sAbilityText_25381524[] = _("进入战斗时,复制一只对手宝可梦\n的特性,替换当前特性栏位中的特\n性.无法复制复制、神奇守护以及\n大多数与形态相关的特性.在双打\n对战中,随机选择首个符合条件的\n对手.");
constexpr u8 __sAbilityText_4195277540[] = _("该宝可梦的攻击能力值变为2倍与\n其他伤害加成效果乘法叠加.");
constexpr u8 __sAbilityText_3861257279[] = _("无论该宝可梦是攻击方还是被攻击\n方,使用接触类招式时有30%的几率\n使对手中毒.");
constexpr u8 __sAbilityText_2654516945[] = _("真气弹必定命中.不受畏缩、威吓\n或惊吓的影响.");
constexpr u8 __sAbilityText_4052837119[] = _("免疫冻伤状态.受到的水属性和冰\n属性招式伤害降低30%.与其他减伤\n效果乘法叠加.");
constexpr u8 __sAbilityText_3106828014[] = _("出场时制造出水环,每回合回复\n1/16的HP.免疫灼伤状态,并在替换\n上场时解除灼伤状态.");
constexpr u8 __sAbilityText_3884536351[] = _("在该宝可梦在场期间,阻止钢属性\n宝可梦替换下场.幽灵属性免疫此\n效果.携带逃脱按键或使用替换招\n式（如快速折返）的宝可梦可以逃\n脱如果在战斗中中途替换上场,效\n果将在下一回合生效.");
constexpr u8 __sAbilityText_1608745061[] = _("免疫声音类招式.以自身为目标的\n声音类招式不受影响.");
constexpr u8 __sAbilityText_196828457[] = _("下雨天气时,每回合结束时回复1/8\n的最大HP.");
constexpr u8 __sAbilityText_3833489428[] = _("出场时引发沙暴,持续8回合（携带\n光滑岩石时为12回合）.每回合对\n非岩石/地面/钢属性宝可梦造成\n1/16的HP伤害岩石属性宝可梦的特\n防提升50%.使与大晴天相关的招式\n效果减半");
constexpr u8 __sAbilityText_2382244582[] = _("对手使用招式时,PP消耗加倍.出场\n时,清除所有对手的能力提升等级.");
constexpr u8 __sAbilityText_1304183046[] = _("受到的火属性和冰属性招式伤害降\n低50%.与其他减伤效果乘法叠加.");
constexpr u8 __sAbilityText_3442864152[] = _("该宝可梦从睡眠状态醒来的速度加\n倍.每回合减少2个睡眠计数而非1\n个.");
constexpr u8 __sAbilityText_3907149169[] = _("与该宝可梦发生接触有30%几率使\n对手灼伤.非接触攻击有20%几率.\n无论攻击方还是被攻击方均会生\n效.");
constexpr u8 __sAbilityText_1361885567[] = _("无论速度如何,必定能从野生宝可\n梦对战中成功逃离.当该宝可梦的\n任何能力被对手的招式或特性降低\n时,其速度提升2级.");
constexpr u8 __sAbilityText_2867319544[] = _("防止命中率能力等级被降低.所有\n招式获得1.2倍的命中率提升.");
constexpr u8 __sAbilityText_2024668271[] = _("巨钳特性防止敌人通过招式或特性\n降低该宝可梦的攻击能力.该宝可\n梦使用的所有接触类招式的击中要\n害率提升1级.");
constexpr u8 __sAbilityText_2148389225[] = _("进入战斗时,清除己方场地上所有\n入场陷阱.该宝可梦在清除陷阱时\n仍会受到它们的影响.");
constexpr u8 __sAbilityText_2089374655[] = _("防止连续使用攻击招式.使用攻击\n招式后,下一回合必须偷懒,无法攻\n击.使用变化招式不受影响.");
constexpr u8 __sAbilityText_2402311279[] = _("攻击招式威力提升40%,但命中率降\n低10%.仅影响非变化招式.");
constexpr u8 __sAbilityText_3079763450[] = _("当通过接触受到攻击时（无论攻击\n方还是被攻击方）,有50%几率使攻\n击者陷入着迷状态（使其攻击和特\n攻减半）.此效果仅对异性宝可梦\n生效.");
constexpr u8 __sAbilityText_1440112971[] = _("当与具有负电或正电的同伴一起出\n战时,该宝可梦的输出威力加倍.");
constexpr u8 __sAbilityText_3371844944[] = _("根据当前的天气改变自身形态和属\n性.当使用改变天气的招式时,会紧\n接着使用气象球（威力100,特殊,\n类型与设置的天气一致）.在出场\n时、天气变化时以及回合结束时触\n发形态变化.此特性无法被压制,即\n使在破格等效果下也能生效.");
constexpr u8 __sAbilityText_1034722447[] = _("该宝可梦携带的物品不会被强制移\n除或偷走.");
constexpr u8 __sAbilityText_2640391524[] = _("每回合结束时,该宝可梦有30%的几\n率治愈自身所受到的异常状态.");
constexpr u8 __sAbilityText_168565646[] = _("处于任何异常状态时,攻击能力值\n提升50%.并且无视灼伤状态带来的\n攻击力降低效果.");
constexpr u8 __sAbilityText_3709735899[] = _("处于任何异常状态时,基础防御能\n力值提升50%.");
constexpr u8 __sAbilityText_3279672790[] = _("污泥浆特性会反转所有吸取招式的\n治疗效果,使攻击者受到伤害.影响\n吸取拳、超级吸取、终极吸取、吸\n血以及类似的吸取类攻击伤害量等\n于原本应恢复的HP.完美克制依赖\n治疗的战术.");
constexpr u8 __sAbilityText_2660132397[] = _("草属性招式威力提升20%,当HP低于\n1/3时提升50%.");
constexpr u8 __sAbilityText_3837813835[] = _("火属性招式威力提升20%,当HP低于\n1/3时提升50%.");
constexpr u8 __sAbilityText_217647394[] = _("水属性招式威力提升20%,当HP低于\n1/3时提升50%.");
constexpr u8 __sAbilityText_3145731659[] = _("虫属性招式威力提升20%,当HP低于\n1/3时提升50%.");
constexpr u8 __sAbilityText_3870381119[] = _("防止所有来自自身招式或特性的反\n伤伤害.同时免疫因愤怒产生的反\n伤伤害无法防止撞击伤害或大爆炸\n/自爆的伤害.");
constexpr u8 __sAbilityText_1293802569[] = _("出场时引发大晴天,持续8回合（携\n带炎热岩石时为12回合）.火属性\n招式威力提升50%,水属性招式威力\n降低50%.并激活与大晴天相关的招\n式的额外效果.");
constexpr u8 __sAbilityText_2618221903[] = _("防止所有非飘浮状态或非幽灵属性\n的对手替换下场.携带逃脱按键或\n使用替换招式（如快速折返）的宝\n可梦可以逃脱如果在战斗中中途替\n换上场,效果将在下一回合生效.");
constexpr u8 __sAbilityText_2406444686[] = _("免疫睡眠状态.当该宝可梦使用格\n斗属性招式时在招式效果结束后立\n即治愈所有异常状态.获得此特性\n时若已睡眠,则立刻解除.");
constexpr u8 __sAbilityText_413538202[] = _("出场时设置烟幕,持续3回合.烟幕\n使己方全队的闪避率提升25%.");
constexpr u8 __sAbilityText_4081840916[] = _("出场时设置顺风,持续3回合,并清\n除所有天气效果.原始天气会被压\n制.在该宝可梦在场期间,天气仍可\n被设置,但不会产生任何效果,直到\n该宝可梦下场.");
constexpr u8 __sAbilityText_3610146995[] = _("当该宝可梦处于混乱或愤怒状态\n时,在伤害计算中使用其速度能力\n值来代替防御或特防.讲究围巾的\n效果不会影响此特性");
constexpr u8 __sAbilityText_2439056433[] = _("免疫电属性招式,并且在受到电属\n性招式攻击时,速度提升1级.对于\n连续攻击招式,每次命中都会触发.");
constexpr u8 __sAbilityText_3200173335[] = _("该宝可梦对同性别的对手造成伤害\n提高25%,受到异性别的对手造成的\n伤害降低25%.对无性别的宝可梦无\n效.");
constexpr u8 __sAbilityText_1353984862[] = _("当陷入畏缩状态时,速度提升1级.");
constexpr u8 __sAbilityText_2925220009[] = _("原本在HP低于1/4时发动的树果,改\n为在HP低于1/2时发动.此外,在消\n耗任何树果后,该宝可梦会额外回\n复1/3的最大HP.不包括通过啄食等\n招式消耗的树果.");
constexpr u8 __sAbilityText_3745959792[] = _("受到攻击时,该宝可梦的攻击提升1\n级；若受到击中要害的攻击,则攻\n击能力值提升至最大.对于连续攻\n击招式,每次命中都会触发.");
constexpr u8 __sAbilityText_2434424917[] = _("当消耗或失去携带的物品时,该宝\n可梦的基础速度能力值变为2倍.当\n替换下场、获得新物品或失去此特\n性时,速度加成消失.");
constexpr u8 __sAbilityText_1055129551[] = _("受到的火属性招式伤害减半.免疫\n灼伤伤害以及灼伤状态带来的攻击\n力降低效果.");
constexpr u8 __sAbilityText_1768922269[] = _("受到水属性招式攻击时回复25%的\nHP,下雨天气时每回合回复12.5%的\nHP.受到火属性招式伤害增加25%,\n大晴天天气时每回合损失12.5%的\nHP.");
constexpr u8 __sAbilityText_2092587340[] = _("替换上场时,如果对手的防御高于\n特防,则自身的特攻提升1级.如果\n对手的特防高于或等于防御则自身\n的攻击提升1级.");
constexpr u8 __sAbilityText_159165311[] = _("拳类招式的威力提升30%.");
constexpr u8 __sAbilityText_3239832715[] = _("处于中毒状态时,每回合回复1/8的\n最大HP,而非受到伤害.对普通中毒\n和剧毒状态均有效.同时免疫剧毒\n地形的伤害.");
constexpr u8 __sAbilityText_2053935012[] = _("使用与自身属性相同的招式时,伤\n害加成从1.5倍提升至2.0倍.");
constexpr u8 __sAbilityText_1935984663[] = _("使连续攻击招式必定打出5次.对于\n仅能攻击3次或使用大扫荡时,所有\n攻击进行一次命中判定,而非每次\n攻击单独判定.");
constexpr u8 __sAbilityText_2036951636[] = _("下雨天气时,每回合结束时治愈所\n有异常状态");
constexpr u8 __sAbilityText_3594502976[] = _("大晴天时,该宝可梦最高的攻击能\n力值提升50%.");
constexpr u8 __sAbilityText_3713636305[] = _("处于任何异常状态时,速度能力值\n提升50%.并且无视麻痹状态带来的\n速度降低效果.");
constexpr u8 __sAbilityText_1922367651[] = _("将所有攻击招式转变为一般属性,\n并给予10%的威力加成.一般属性招\n式可以无视属性抗性但无法无视属\n性免疫.");
constexpr u8 __sAbilityText_3125945689[] = _("击中要害时的伤害倍率从1.5倍提\n升至2.25倍,即额外增加50%的伤害\n加成.");
constexpr u8 __sAbilityText_509172936[] = _("免疫所有非攻击性的伤害来源,包\n括入场陷阱、天气伤害、异常状态\n以及反伤伤害.");
constexpr u8 __sAbilityText_3250891130[] = _("确保该宝可梦使用的所有招式以及\n所有对该宝可梦使用的招式必定命\n中.");
constexpr u8 __sAbilityText_1038029421[] = _("如果该宝可梦本回合还未行动,则\n受到的伤害降低30%.与其他减伤效\n果乘法叠加.当该宝可梦在回合中\n替换上场时也生效.");
constexpr u8 __sAbilityText_1400379598[] = _("威力小于等于60的招式威力提升\n1.5倍.对于基础威力可能超过60的\n招式（如复仇或毒击）,即使当前\n威力小于等于60,也不会获得提升.");
constexpr u8 __sAbilityText_93816716[] = _("大晴天时,每回合结束时治愈所有\n异常状态");
constexpr u8 __sAbilityText_2120372401[] = _("使所有携带物品的效果失效.物品\n仍可以被打落或偷走,但不会提供\n任何增益.投掷等依赖物品的招式\n会失败.超级石不受此限制.");
constexpr u8 __sAbilityText_1911702217[] = _("允许招式无视目标的特性和先天特\n性,包括那些会干扰效果或降低伤\n害的特性.无法绕过那些会修改基\n础能力值的特性,如草之皮毛.");
constexpr u8 __sAbilityText_1865557032[] = _("该宝可梦所有攻击招式的击中要害\n率提升1级.");
constexpr u8 __sAbilityText_1361310431[] = _("当该宝可梦被击倒时,使用威力100\n的大爆炸或迸裂拳（取两者中威力\n更高者）.使用爆炸类招式时,必定\n使目标畏缩.");
constexpr u8 __sAbilityText_2335442336[] = _("替换上场时,若对手拥有对自身效\n果绝佳的招式,则会收到警告.闪避\n战斗中受到的第一次效果绝佳的招\n式攻击.");
constexpr u8 __sAbilityText_2454906435[] = _("替换上场时,对目标对手施放一个\n威力80的预知未来.2回合后攻击,\n可穿透替身和其他保护效果.一旦\n施放必定命中,无视命中判定.无法\n对同一目标施放两次.");
constexpr u8 __sAbilityText_3083638037[] = _("进行伤害计算时,完全无视对手的\n所有能力等级变化.");
constexpr u8 __sAbilityText_2573433447[] = _("攻击被抵抗时,伤害加倍.如果招式\n被抵抗（伤害减半或更低）,则最\n终伤害乘以2倍.");
constexpr u8 __sAbilityText_2801527524[] = _("受到效果绝佳的招式攻击时,伤害\n降低35%.与其他减伤效果乘法叠\n加.");
constexpr u8 __sAbilityText_230822820[] = _("替换上场后的前5回合,攻击、特攻\n和速度能力值减半.每次替换下场\n后,回合计数会重置.");
constexpr u8 __sAbilityText_1025757613[] = _("该宝可梦使用的一般和格斗属性招\n式能够以普通效果击中幽灵属性宝\n可梦.免疫威吓和惊吓.");
constexpr u8 __sAbilityText_4191063160[] = _("该宝可梦会吸引水属性招式,并对\n其免疫.此外,受到水属性招式攻击\n后,自身最高的攻击能力提升1级.");
constexpr u8 __sAbilityText_1192364337[] = _("冰雹天气时,每回合结束时回复1/8\n的最大HP.同时免疫冰雹伤害.");
