constexpr u8 __sAbilityText_2434552999[] = _("如果未携带物品,每回合有50%的几\n率获得甜甜蜜.甜甜蜜每回合可回\n复1/16的HP,并可在危急时食用以\n回复1/4的HP.即使该宝可梦最初未\n携带甜甜蜜作为物品,此效果也有\n效.");
constexpr u8 __sAbilityText_804642340[] = _("进入战斗时,揭示对手的物品,并使\n其效果失效2回合.此效果不会阻止\n超级石及其他类似物品的运作.");
constexpr u8 __sAbilityText_1384573068[] = _("会造成反伤伤害的招式威力提升\n20%.此加成也适用于通过其他方式\n（如疯狂状态或特性）获得反伤效\n果的招式.");
constexpr u8 __sAbilityText_2422537703[] = _("该宝可梦根据其当前携带的石板的\n属性改变形态.石板无法被移除,并\n且多重属性特性无法以任何方式被\n覆盖、压制、交换或复制.");
constexpr u8 __sAbilityText_582312216[] = _("在大晴天时,该宝可梦及其所有同\n伴的基础特攻和特防提升50%.");
constexpr u8 __sAbilityText_3640094543[] = _("所有处于睡眠状态的对手每回合结\n束时损失25%的最大HP.");
