constexpr u8 __sAbilityText_2014319284[] = _("在攻击命中后,移除大部分有益的\n追加效果,以获得1.3倍的威力提升.\n使用此类招式时,显著特点是不会\n受到生命宝珠的反伤.可被移除的\n效果包括：降低目标能力、提升自\n身能力、施加异常状态以及造成畏\n缩.");
constexpr u8 __sAbilityText_877183825[] = _("反转影响该宝可梦的所有能力变\n化.对自身引起的能力变化同样有\n效.");
constexpr u8 __sAbilityText_3682543073[] = _("阻止所有对手宝可梦消耗其携带的\n物品.");
