constexpr u8 __sAbilityText_2739751287[] = _("在双打对战中,每回合结束时,有\n30%的几率治愈自身和场上同伴的\n异常状态.对两只宝可梦分别进行\n几率判定.");
constexpr u8 __sAbilityText_3815541120[] = _("在双打对战中,该宝可梦的同伴受\n到伤害降低50%.与其他减伤来源乘\n法叠加.");
constexpr u8 __sAbilityText_2935283312[] = _("受到接触招式攻击时,该宝可梦的\n速度提升2级,防御降低1级.对于连\n续攻击招式,每次命中都会触发.");
