constexpr u8 __sAbilityText_167387148[] = _("处于灼伤状态时,该宝可梦的特攻\n能力值提升50%.无视灼伤伤害.在\n雾天时立刻让自己陷入灼伤状态.");
constexpr u8 __sAbilityText_2364449736[] = _("每回合结束时,有50%几率回收已使\n用的树果大晴天时100%回收.包括\n用于投掷、自然恩惠或被吃掉的树\n果.");
constexpr u8 __sAbilityText_2222841076[] = _("在双打对战中,保护该宝可梦免受\n其同伴使用的所有造成伤害的招式\n的影响.");
