constexpr u8 __sAbilityText_4176910092[] = _("免疫沙暴和冰雹的天气伤害,并阻\n挡所有粉末类招式,包括催眠粉、\n麻痹粉、毒粉、蘑菇孢子、棉孢\n子、愤怒粉、粉末和魔法粉.同时,\n受到的特殊伤害降低20%.与其他减\n伤来源乘法叠加.");
