constexpr u8 __sAbilityText_625655034[] = _("变化类招式获得+1优先度.当直接\n以恶属性宝可梦为目标时变化招式\n会失败.");
constexpr u8 __sAbilityText_3500041910[] = _("在沙暴中,该宝可梦最高的攻击能\n力值提升50%.免疫沙暴伤害.");
constexpr u8 __sAbilityText_1023851993[] = _("进入战斗时触发形态变化.");
