constexpr u8 __sAbilityText_1711741052[] = _("允许招式无视目标的特性和先天特\n性,包括那些会干扰效果或降低伤\n害的特性.无法绕过会修改基础能\n力值的特性,如草之皮毛.为自身添\n加火属性.即使失去此特性,添加的\n火属性在替换下场前依然保留.");
constexpr u8 __sAbilityText_956150588[] = _("允许招式无视目标的特性和先天特\n性,包括那些会干扰效果或降低伤\n害的特性.无法绕过会修改基础能\n力值的特性,如草之皮毛.为自身添\n加电属性.即使失去此特性,添加的\n电属性在替换下场前依然保留.");
constexpr u8 __sAbilityText_249880373[] = _("保护该宝可梦及其同伴免受着迷、\n回复封锁效果以及封印类招式（包\n括封印、挑衅、再来一次和无理取\n闹）的影响.");
constexpr u8 __sAbilityText_3843549281[] = _("防止草属性同伴陷入任何异常状态\n或能力降低.包括自身引起的能力\n降低.");
constexpr u8 __sAbilityText_802688378[] = _("无效果.");
constexpr u8 __sAbilityText_2918370809[] = _("每次攻击前,该宝可梦的属性会变\n为与所用招式相同的属性.每回合\n触发一次.");
constexpr u8 __sAbilityText_3759121558[] = _("所有受到的物理攻击伤害减半.与\n其他减伤来源乘法叠加.");
constexpr u8 __sAbilityText_706762959[] = _("如果该宝可梦当前未携带物品,使\n用非接触类招式命中后,会偷走目\n标携带的物品.对超级石及其他类\n似物品无效.");
constexpr u8 __sAbilityText_1413479244[] = _("免疫球、炸弹和投射物类招式.包\n括酸液炸弹、岩石炮、花粉团和投\n球.");
constexpr u8 __sAbilityText_3613751610[] = _("当该宝可梦的能力被其他宝可梦降\n低时,其特攻能力提升2级.");
constexpr u8 __sAbilityText_3806454179[] = _("啃咬和颚类招式的威力提升30%.");
constexpr u8 __sAbilityText_376354639[] = _("将该宝可梦的一般属性招式变为冰\n属性.如果该宝可梦是冰属性,其冰\n属性招式有10%的几率造成冻伤；\n否则,它获得冰属性的本系加成.");
