constexpr u8 __sAbilityText_693890267[] = _("在青草场地中,该宝可梦的防御能\n力值提升50%.");
constexpr u8 __sAbilityText_2572064940[] = _("在同伴消耗或使用掉其携带的物品\n后,立即将持有者的物品传递给该\n同伴.");
constexpr u8 __sAbilityText_3391815883[] = _("将该宝可梦的一般属性招式变为妖\n精属性.如果该宝可梦是妖精属性,\n其妖精属性招式有10%的几率造成\n着迷；否则,它获得妖精属性的本\n系加成.");
constexpr u8 __sAbilityText_1602795543[] = _("当该宝可梦受到接触招式攻击时,\n攻击者的速度降低1级.对于连续攻\n击招式,每次命中都会触发.");
constexpr u8 __sAbilityText_328175044[] = _("将该宝可梦的一般属性招式变为飞\n行属性.如果该宝可梦是飞行属性,\n其飞行属性招式的速度提升10%；\n否则,它获得飞行属性的本系加成.");
constexpr u8 __sAbilityText_3591746934[] = _("使所有攻击连续命中两次.第一击\n造成100%伤害,第二击造成25%伤\n害.每次攻击独立判定追加效果\n（畏缩除外）.可穿透坚壁/奇迹皮\n肤.");
constexpr u8 __sAbilityText_2364046844[] = _("使用者、其同伴以及对手的所有恶\n属性招式获得1.33倍的威力提升.\n此加成会被气场破坏反转.");
constexpr u8 __sAbilityText_1830934292[] = _("使用者、其同伴以及对手的所有妖\n精属性招式获得1.33倍的威力提\n升.此加成会被气场破坏反转.");
constexpr u8 __sAbilityText_4101972299[] = _("使暗黑气场和妖精气场的效果反\n转,将其对应属性的招式威力降低\n25%,而非提升33%.");
constexpr u8 __sAbilityText_1041645308[] = _("创造终焉大雨,持续到使用者下场.\n完全无效所有造成伤害的火属性招\n式.水属性招式获得50%威力提升除\n其他原始天气外,无法被覆盖.激活\n与雨天相关招式的额外效果使与大\n晴天相关的招式效果减半.");
constexpr u8 __sAbilityText_2690859501[] = _("创造终焉大晴天,持续到使用者下\n场.完全无效所有造成伤害的水属\n性招式.火属性招式获得50%威力提\n升除其他原始天气外,无法被覆盖.\n激活与大晴天相关招式的额外效\n果.");
constexpr u8 __sAbilityText_960751703[] = _("创造强风,持续到使用者下场.将场\n上所有飞行属性宝可梦受到的效果\n绝佳伤害变为普通伤害.阻止所有\n基于天气的招式命中对手.除其他\n原始天气外,无法被覆盖.");
constexpr u8 __sAbilityText_3652412048[] = _("受到攻击时,该宝可梦的防御提升1\n级；若受到击中要害的攻击,则防\n御能力值提升至最大.对于连续攻\n击招式,每次命中都会触发.");
constexpr u8 __sAbilityText_626237269[] = _("当该宝可梦受到伤害,且HP在战斗\n中首次降至50%或以下时,它会替换\n下场以保安全.对于连续攻击招式,\n在最后一击后触发.");
constexpr u8 __sAbilityText_2771750327[] = _("受到的水属性招式伤害降低50%,并\n且被水属性招式击中后,防御提升2\n级.与其他减伤来源乘法叠加.防御\n提升效果在攻击命中后生效对于连\n续攻击招式,每次命中都会触发.");
constexpr u8 __sAbilityText_2767714728[] = _("对处于中毒、麻痹、流血或速度降\n低状态的目标,必定造成击中要害.");
constexpr u8 __sAbilityText_3501177111[] = _("当小陨星的HP降至50%或以下时,从\n流星形态变身为核心形态.在流星\n形态下,免疫所有异常状态.使用破\n壳时,无论当前HP多少,立即变身为\n核心形态.在战斗中一旦变身,无法\n恢复为流星形态.");
constexpr u8 __sAbilityText_1005118568[] = _("对刚替换上场的对手造成双倍伤\n害.仅在对手替换上场后的第一回\n合内生效.");
constexpr u8 __sAbilityText_2513613582[] = _("水属性招式威力加倍,受到的火属\n性伤害降低50%.同时完全免疫灼\n伤,并在获得此特性时移除已有的\n灼伤状态.");
constexpr u8 __sAbilityText_2290776584[] = _("将该宝可梦的一般属性招式变为钢\n属性.如果该宝可梦是钢属性,它获\n得对幽灵和恶属性的抗性；否则,\n它获得钢属性的本系加成.");
constexpr u8 __sAbilityText_2409956906[] = _("当该宝可梦因对手的攻击而使HP降\n至一半或以下时,其最高的攻击能\n力值提升1级.根据能力等级决定提\n升哪一项.每场战斗仅触发一次.其\n他伤害来源使HP降至一半或以下不\n会触发此特性.");
constexpr u8 __sAbilityText_3533089551[] = _("在冰雹中,该宝可梦的速度能力值\n提升50%.同时免疫冰雹伤害.");
constexpr u8 __sAbilityText_2234787934[] = _("远隔特性防止该宝可梦在使用接触\n类招式时与目标发生接触.此外,物\n理招式获得1.2倍的伤害加成.");
constexpr u8 __sAbilityText_2927675708[] = _("湿润之声将一般属性的声音类招式\n转变为水属性,并将其威力提升\n20%.");
constexpr u8 __sAbilityText_473069161[] = _("治愈之心给予大多数回复类招式\n+3优先度.包括终极吸取等吸取类\n招式,以及祈愿等延迟回复招式.对\n水流环、青草场地、扎根、寄生种\n子、痛平分、礼物或花粉团无效.");
constexpr u8 __sAbilityText_3777452772[] = _("将该宝可梦的一般属性招式变为电\n属性.如果该宝可梦是电属性,其电\n属性招式有10%的几率造成麻痹；\n否则,它获得电属性的本系加成.");
constexpr u8 __sAbilityText_2955187360[] = _("在电气场地生效时,该宝可梦的速\n度能力值提升50%.场地开始时立即\n生效,场地结束时加成消失.");
constexpr u8 __sAbilityText_2178520211[] = _("当等级达到20或以上时,变身为鱼\n群形态.当HP降至25%或以下时,恢\n复为单独形态.此形态变化在出场\n时和每回合结束时自动触发.无法\n以任何方式覆盖、压制、交换或复\n制.");
constexpr u8 __sAbilityText_3030511988[] = _("画皮会抵挡第一个命中该宝可梦的\n造成伤害的招式,之后改变形态.仅\n能抵挡非变化招式.在雾中,每次替\n换上场或当雾重新出现时,画皮会\n立即恢复.");
constexpr u8 __sAbilityText_3093082919[] = _("当该宝可梦给予对手最后一击使其\n濒死时,立即触发形态变化.无法被\n复制.");
constexpr u8 __sAbilityText_2004927591[] = _("群聚变形会在任何回合结束时,如\n果基格尔德50%或10%形态的HP降至\n50%或以下,则使其变身为完全体形\n态.完全体形态拥有高达216的HP\n（从108翻倍）,使其成为极其耐打\n的坦克.此形态变化在战斗中永久\n持续,且无法被压制.");
constexpr u8 __sAbilityText_2650864743[] = _("毒属性招式对钢属性宝可梦变得效\n果绝佳.此外,该宝可梦可以使任何\n属性的宝可梦陷入中毒状态.");
constexpr u8 __sAbilityText_4033749603[] = _("绝对睡眠特性使该宝可梦在招式和\n状态判定中被视为处于睡眠状态.\n该宝可梦可以正常行动,并且免疫\n所有异常状态.此特性无法被复制\n或压制.使用招式睡觉会失败.");
constexpr u8 __sAbilityText_3274366813[] = _("女王威严防止该宝可梦及其同伴成\n为优先度大于0的先制招式的目标.");
constexpr u8 __sAbilityText_2084529644[] = _("当该宝可梦被对手的攻击击倒时,\n会向攻击者返还与致命一击等量的\n伤害.对拥有魔法防守特性的攻击\n者无效.");
constexpr u8 __sAbilityText_1486164680[] = _("当场上任何宝可梦使用舞蹈类招式\n后,该宝可梦会立即使用相同的招\n式每回合对每个招式触发一次.");
constexpr u8 __sAbilityText_679427807[] = _("在双打对战中,蓄电池为同伴宝可\n梦的特殊攻击提供30%的威力提升.\n不影响使用者自身的招式.");
constexpr u8 __sAbilityText_671123263[] = _("毛茸茸使受到的接触类招式伤害降\n低50%.火属性招式对该宝可梦造成\n双倍伤害.与其他减伤效果乘法叠\n加.");
constexpr u8 __sAbilityText_4171771930[] = _("棱镜装甲阻挡所有来自对手的、以\n该宝可梦或其同伴为目标的先制招\n式.");
constexpr u8 __sAbilityText_1508679399[] = _("当战场上任何宝可梦（包括同伴和\n对手）濒死时,魂心特性会提升该\n宝可梦的特攻1级.");
constexpr u8 __sAbilityText_3174934590[] = _("接球手会复制濒死同伴的特性,替\n换自身的接球手特性.此效果持续\n到替换下场.");
constexpr u8 __sAbilityText_1142289583[] = _("出场时,将所有对手的树果转化为\n黑色污泥.战斗中任何宝可梦失去\n物品时,该物品会被黑色污泥取代.\n如果黑色污泥被移除,则会被大金\n珠取代.");
constexpr u8 __sAbilityText_2453184276[] = _("每当该宝可梦击倒一名对手时,其\n最高的计算后能力值提升1级被提\n升的能力基于不考虑当前能力等级\n变化的原始能力值决定.");
constexpr u8 __sAbilityText_2576954429[] = _("AR系统根据携带的记忆碟改变使用\n者的形态.每次攻击前,使用者的属\n性会变为与所用招式相同的属性.\n本系加成从1.5倍提升至2.0倍.");
constexpr u8 __sAbilityText_1526237033[] = _("出场时制造电气场地,持续8回合\n（携带场地制造机时为12回合）.\n地面上的宝可梦不会陷入睡眠,且\n电属性招式威力提升30%.激活时覆\n盖其他场地.");
constexpr u8 __sAbilityText_2832919612[] = _("出场时制造精神场地,持续8回合\n（携带场地制造机时为12回合）.\n地面上的宝可梦免疫对手的先制招\n式.超能力属性招式威力提升30%.\n广阔战场可以攻击所有对手且威力\n提升.自然之力变为精神强念.覆盖\n其他现有场地.");
constexpr u8 __sAbilityText_4022539575[] = _("出场时制造薄雾场地,持续8回合\n（携带场地制造机时为12回合）.\n薄雾场地防止地面上的宝可梦陷入\n任何异常状态,并使妖精属性招式\n威力提升30%.覆盖现有场地.");
constexpr u8 __sAbilityText_1651650823[] = _("出场时制造青草场地,持续8回合\n（携带场地制造机时为12回合）地\n面上的宝可梦每回合回复1/16的\nHP,且草属性招式威力提升30%.覆\n盖其他场地.");
constexpr u8 __sAbilityText_143472945[] = _("金属防护使该宝可梦免疫所有来自\n招式或特性的能力降低效果.包括\n因使用过热等招式导致的自身能力\n降低.");
constexpr u8 __sAbilityText_513249244[] = _("当HP全满时,幻影防守使受到的所\n有攻击伤害减半.与其他减伤来源\n乘法叠加.");
constexpr u8 __sAbilityText_511819414[] = _("效果绝佳的攻击威力提升35%.");
constexpr u8 __sAbilityText_1435892899[] = _("不挠之剑在替换上场时,使该宝可\n梦的攻击能力提升1级.");
constexpr u8 __sAbilityText_3980056033[] = _("不屈之盾在进入战斗时,立即将防\n御能力提升1级.");
constexpr u8 __sAbilityText_2715889072[] = _("自由者在攻击前,会将使用者的属\n性覆盖为与所用招式相同的属性.\n挣扎招式无法触发此效果.");
constexpr u8 __sAbilityText_3013552855[] = _("棉絮特性在该宝可梦受到任何攻击\n时触发,降低所有宝可梦的速度1\n级.对于连续攻击招式,每次命中都\n会触发.");
constexpr u8 __sAbilityText_703900577[] = _("螺旋尾鳍使该宝可梦在雨天时速度\n提升50%,并且免疫招式吸引效果.\n速度加成在所有形式的雨天中都有\n效.");
constexpr u8 __sAbilityText_3273728243[] = _("镜甲将所有以该宝可梦为目标的降\n低能力效果反弹给攻击者.反弹效\n果无视免疫.");
constexpr u8 __sAbilityText_545840341[] = _("当古月鸟使用冲浪、三重潜水或潜\n水时,它会叼住猎物：HP小于50%时\n为叼喙形态,HP大于50%时为吞喙形\n态.在任一形态下受到攻击时,会向\n攻击者吐出猎物,造成其最大HP25%\n的伤害,并返回普通形态.叼喙形态\n还会降低防御1级；吞喙形态会麻\n痹目标.此特性无法被压制等.");
constexpr u8 __sAbilityText_1137842640[] = _("招式不会被吸引,不会受到击中要\n害,且特性不会被压制.特性压制包\n括破格、化学变化气体和菌丝之力\n等效果.");
constexpr u8 __sAbilityText_1563149922[] = _("受到任何火属性或水属性招式攻击\n后,蒸汽机特性立即将速度能力值\n提升至+6级.提升效果在受到伤害\n后生效.");
constexpr u8 __sAbilityText_3531903765[] = _("庞克摇滚使该宝可梦的声音类招式\n威力提升30%,并且受到的声音类招\n式伤害降低50%.伤害减免与其他来\n源乘法叠加.");
constexpr u8 __sAbilityText_2739230591[] = _("受到攻击伤害时,如果场上没有沙\n暴,则会引发持续8回合的沙暴.如\n果沙暴被引发,攻击者会被拉至地\n面.该宝可梦免疫沙暴伤害.如果该\n宝可梦因该次攻击而濒死则不会触\n发此特性.");
constexpr u8 __sAbilityText_747494306[] = _("所有受到的特殊攻击伤害减半.与\n其他减伤来源乘法叠加.");
constexpr u8 __sAbilityText_2060035306[] = _("熟成使所有树果的有益效果加倍回\n复类树果回复量加倍,提升能力的\n树果改为提升2级,抵抗树果将效果\n绝佳的伤害降低75%而非50%,回复\nPP的树果回复量加倍.");
constexpr u8 __sAbilityText_2691273062[] = _("结冻头使哭哭面具在受到物理攻击\n后变身为无头形态,并抵消一次伤\n害.在无头形态下,如果场上出现冰\n雹或该宝可梦被替换上场,则恢复\n为结冻头形态.无法被复制或压制.");
constexpr u8 __sAbilityText_3389771831[] = _("在双打对战中,能量点使同伴的攻\n击威力提升30%.使用者自身不受此\n加成影响.");
constexpr u8 __sAbilityText_3051978459[] = _("拟态使该宝可梦的属性变为与当前\n场地一致：电气场地变为电属性,\n薄雾场地变为妖精属性,青草场地\n变为草属性,精神场地变为超能力\n属性.属性变化持续到场地结束或\n该宝可梦下场.保留通过浸水等招\n式改变的属性.");
constexpr u8 __sAbilityText_2165325422[] = _("除障特性在该宝可梦进入战斗时,\n移除双方场地上所有的防护屏障、\n反射壁、光墙、极光幕和烟幕它还\n允许该宝可梦在屏障已激活时重新\n设置它们,刷新其持续时间.");
constexpr u8 __sAbilityText_124182405[] = _("钢魂特性在战斗中使使用者及其同\n伴的钢属性招式威力提升30%.");
constexpr u8 __sAbilityText_3581127551[] = _("受到接触招式攻击时,灭亡之躯对\n使用者和攻击者发动灭亡之歌.除\n非替换下场,否则两只宝可梦将在3\n回合后濒死.");
constexpr u8 __sAbilityText_968148307[] = _("受到接触招式攻击时,游魂特性会\n与攻击者交换特性.两只宝可梦在\n替换下场后恢复各自原有的特性.\n无法与同样不能被复制或压制的特\n性交换.");
constexpr u8 __sAbilityText_1141264833[] = _("一猩一意使物理招式威力提升50%,\n但会锁定使用者只能使用首次选择\n的招式,直到替换下场.");
constexpr u8 __sAbilityText_1283451900[] = _("用气体充满战场,完全压制除无法\n压制外的所有特性.效果在使用者\n在场时持续.在使用者尝试替换下\n场后,所有被压制的特性会重新触\n发其入场效果.无法被复制或交换.");
constexpr u8 __sAbilityText_3580909547[] = _("粉彩护幕在该宝可梦进入战斗时,\n自动为其队伍设置神秘守护.神秘\n守护持续5回合,保护所有队友免受\n异常状态.");
constexpr u8 __sAbilityText_91327335[] = _("每回合结束时自动在吃饱形态和饥\n饿形态之间切换.无法以任何方式\n覆盖、压制、交换或复制.");
constexpr u8 __sAbilityText_1884143333[] = _("速击有30%的几率让使用者在当前\n优先度层级内率先行动.与先制之\n爪的效果乘法叠加,使总触发几率\n达到44%.");
constexpr u8 __sAbilityText_1014897552[] = _("无形拳允许所有接触类招式穿透保\n护类招式,并忽略与其相关的任何\n附加效果.");
constexpr u8 __sAbilityText_2375519649[] = _("怪药在使用者出场时,移除同伴的\n所有正向和负向能力变化.");
constexpr u8 __sAbilityText_3263362325[] = _("电晶体使所有电属性招式的威力提\n升50%.与其他伤害加成效果加法叠\n加.");
constexpr u8 __sAbilityText_1006785025[] = _("龙颚使龙属性招式的威力提升50%.");
constexpr u8 __sAbilityText_4235604360[] = _("当该宝可梦通过直接攻击击倒对手\n时,其攻击能力值提升1级.");
constexpr u8 __sAbilityText_1902911130[] = _("漆黑嘶鸣特性在该宝可梦通过直接\n攻击使对手濒死时,提升其特攻能\n力值1级.");
constexpr u8 __sAbilityText_2813844621[] = _("阻止所有对手宝可梦消耗其携带的\n物品.当该宝可梦通过直接攻击击\n倒对手时,其攻击能力值提升1级.");
constexpr u8 __sAbilityText_2979571791[] = _("阻止所有对手宝可梦消耗其携带的\n物品.当该宝可梦通过直接攻击击\n倒对手时,其特攻能力值提升1级.");
