constexpr u8 __sAbilityText_2771466140[] = _("进入战斗时,为使用者的当前属性\n添加龙属性即使失去此特性,添加\n的龙属性在替换下场前依然保留.");
constexpr u8 __sAbilityText_2045753353[] = _("液化使受到的接触类招式伤害降低\n50%,但受到的水属性招式伤害变为\n2倍.与其他减伤来源乘法叠加.");
