constexpr u8 __sAbilityText_1873426368[] = _("效果绝佳的攻击招式必定命中,并\n且必定造成击中要害.");
constexpr u8 __sAbilityText_1581666791[] = _("如果使用者是草属性,其受到的火\n属性攻击伤害减半,并且使用草属\n性招式对火属性宝可梦造成2倍伤\n害.伤害减免与其他来源乘法叠加.");
constexpr u8 __sAbilityText_157064627[] = _("超能力属性招式威力提升20%,当HP\n低于1/3时提升50%.");
