constexpr u8 __sAbilityText_20460975[] = _("使用者替换上场后的第一回合,获\n得50%的速度加成和20%的攻击加\n成.");
constexpr u8 __sAbilityText_4267256141[] = _("当HP全满时,赋予火属性招式+1优\n先度.");
constexpr u8 __sAbilityText_4108399073[] = _("特攻能力值提升50%,但会将使用者\n锁定在首次选择的招式上,直到替\n换下场.");
constexpr u8 __sAbilityText_3995959234[] = _("骨类招式可以穿透免疫造成正常伤\n害,而对被抵抗的目标则造成2倍伤\n害.普通/效果绝佳的伤害保持不\n变.");
constexpr u8 __sAbilityText_1942728766[] = _("免疫基于天气的招式：打雷、日光\n束/刃、暴风、暴风雪、银色旋\n风、气象球、所有风暴类招式（不\n包括岩浆风暴、飞叶风暴或钻石风\n暴）、绝对零度和誓约招式.不阻\n止天气的设置或其伤害.");
constexpr u8 __sAbilityText_1340097942[] = _("使用接触类招式时,将使用者20%的\n速度能力值加入伤害计算.讲究围\n巾的效果不影响此特性.");
constexpr u8 __sAbilityText_3319423906[] = _("在雨天天气下进入战斗时,海洋守\n护者使你最高的能力值提升1级.适\n用于任何形式的雨天.每次替换上\n场触发一次.");
constexpr u8 __sAbilityText_3717649224[] = _("熔解使火属性招式对岩石属性宝可\n梦变得效果绝佳,而非被抵抗.");
constexpr u8 __sAbilityText_520989465[] = _("使所有攻击连续命中两次.第一击\n造成100%伤害,第二击造成25%伤\n害.每次攻击独立判定追加效果\n（畏缩除外）.");
constexpr u8 __sAbilityText_2896885764[] = _("飞行属性招式威力提升20%,当HP低\n于1/3时提升50%.");
constexpr u8 __sAbilityText_985465810[] = _("将在野外可以使用的招式威力提升\n50%.包括所有秘传技招式、（意念\n头锤/）头锤、冰旋、觉醒力量/自\n然之力和挖洞.");
constexpr u8 __sAbilityText_4275348764[] = _("前锋使所有踢腿类招式的威力提升\n30%.包括火焰球.");
constexpr u8 __sAbilityText_2575803333[] = _("冰霜之魂在使用者HP全满时,赋予\n所有冰属性招式+1优先度.");
constexpr u8 __sAbilityText_1944337805[] = _("月食使妖精属性和恶属性招式获得\n本系加成,无论使用者的属性如何.\n将催眠术的命中率提升至90%.");
constexpr u8 __sAbilityText_1558151414[] = _("将一般属性招式转变为火属性并获\n得火属性本系加成.如果使用者是\n火属性,其火属性招式有10%的几率\n造成灼伤.此外,为使用者的招式激\n活所有与大晴天相关的效果.");
constexpr u8 __sAbilityText_1583288863[] = _("计算伤害时,物理攻击额外增加20%\n的防御能力值,特殊攻击额外增加\n20%的特防能力值.");
constexpr u8 __sAbilityText_2906866143[] = _("瞄准系统确保所有招式无视命中判\n定,必定命中.基础命中率低于80%\n的招式获得-3优先度.");
constexpr u8 __sAbilityText_810405053[] = _("未实装.");
constexpr u8 __sAbilityText_1126858554[] = _("当目标对手的HP为50%或以下时,赋\n予所有招式+1优先度.");
constexpr u8 __sAbilityText_1976239460[] = _("巨翼使所有翅膀、风和空气类招式\n的威力提升30%.");
constexpr u8 __sAbilityText_1874237968[] = _("接触类招式使用速度能力值而非攻\n击/特攻进行伤害计算.讲究围巾的\n效果不影响此特性.");
constexpr u8 __sAbilityText_3641388777[] = _("接触类招式有50%几率束缚目标\n（如捆绑）,防止其逃跑或替换.对\n抗被束缚的目标时,使用者的招式\n无视其防御能力变化并必定命中.\n被束缚的目标每回合损失1/8的最\n大HP.束缚持续4-5回合（携带紧绑\n钩爪时为7回合）.");
constexpr u8 __sAbilityText_3636781447[] = _("为使用者的招式激活所有与大晴天\n相关的效果.在大晴天下速度提升\n50%.在大晴天下治愈异常状态.每\n回合结束时有50%几率回收树果,大\n晴天下为100%.在大晴天下,自身最\n高的攻击能力值提升50%.");
constexpr u8 __sAbilityText_3701076193[] = _("拳类招式获得+1击中要害率,并且\n其原本的追加效果触发几率变为5\n倍.");
constexpr u8 __sAbilityText_2539331927[] = _("使用者不会打空箭矢类攻击和炮类\n招式（与超级发射器招式不同,包\n括被防弹阻挡的招式）.此外,当造\n成击中要害时,攻击目标改为对手\n较弱的防御能力值.");
constexpr u8 __sAbilityText_1527818178[] = _("超级发射器类招式必定命中,并同\n时攻击双方对手.所有脉冲、波\n导、波动、光环及其他爆裂相关招\n式不会打空.");
constexpr u8 __sAbilityText_670659216[] = _("扩音器使声音类招式威力提升30%.\n单体目标的声音类招式变为范围攻\n击,同时攻击双方对手.连续攻击招\n式不会变为范围攻击.");
constexpr u8 __sAbilityText_1128231488[] = _("将所有冰属性招式吸引到该宝可梦\n身上并吸收.吸收冰属性招式时,提\n升攻击或特攻中较高的一项1级.");
constexpr u8 __sAbilityText_2586124117[] = _("在大晴天天气下进入战斗时,使使\n用者最高的能力值提升1级.");
constexpr u8 __sAbilityText_4108049250[] = _("将该宝可梦的一般属性招式变为虫\n属性.如果该宝可梦是虫属性,它免\n疫粉末类招式；否则,它获得虫属\n性的本系加成.");
constexpr u8 __sAbilityText_2525627785[] = _("使用任何火属性招式后,火山之怒\n会触发一次后续的喷火攻击,基础\n威力为50.伤害根据使用者当前的\nHP比例变化,满HP时威力为50.");
constexpr u8 __sAbilityText_978885474[] = _("受到任何接触招式攻击时,冰冷反\n击会以冰息（60威力）进行反击,\n并降低攻击者的速度1级.");
constexpr u8 __sAbilityText_2874443008[] = _("下流打击在替换上场时,使用威力\n40的暗算攻击随机一名对手.暗算\n是恶属性物理攻击,必定命中.");
constexpr u8 __sAbilityText_1347806650[] = _("造成接触的招式额外造成20%的伤\n害,并使使用者回复伤害量的一半\nHP.此回复在连续攻击的所有命中\n之后以及反伤结算之后生效.");
constexpr u8 __sAbilityText_2710037525[] = _("将使用者的一般属性招式变为幽灵\n属性.如果使用者是幽灵属性,其幽\n灵属性招式有10%的几率造成恐\n惧；否则,它获得幽灵属性的本系\n加成.其所有招式（包括变化招\n式）有30%的几率使目标陷入剧毒.");
constexpr u8 __sAbilityText_203514130[] = _("使用狂暴招式（如逆鳞、暴怒）期\n间\n可替换下场。免疫混乱、\n威吓与惊吓。获得此特性时\n立即解除混乱。");
constexpr u8 __sAbilityText_1927805241[] = _("使用任何电属性招式后,雷召会自\n动触发一次后续的天谴攻击,威力\n为20%（基础威力24）这个物理电\n属性攻击命中率为80%,有20%的几\n率使目标麻痹,并施加击落效果使\n飞行属性宝可梦接地.");
constexpr u8 __sAbilityText_204696201[] = _("对水属性宝可梦造成1.5倍伤害,并\n穿透防御屏障（光墙、反射壁、极\n光幕）/替身.");
constexpr u8 __sAbilityText_3326624789[] = _("强大之角使角类和钻类攻击的威力\n提升30%.");
constexpr u8 __sAbilityText_1875661367[] = _("每次成功的角类攻击命中后,使用\n者的攻击能力值提升1级.");
constexpr u8 __sAbilityText_963769284[] = _("使受到的物理和特殊伤害降低35%.\n与其他减伤来源乘法叠加.");
constexpr u8 __sAbilityText_111064185[] = _("将使用者的一般属性招式变为幽灵\n属性.如果使用者是幽灵属性,其幽\n灵属性招式有10%的几率造成恐\n惧；否则,它获得幽灵属性的本系\n加成.");
constexpr u8 __sAbilityText_3863926330[] = _("每回合开始时,使用者的总伤害降\n低20%,最多降低80%.替换后重置.");
constexpr u8 __sAbilityText_655837743[] = _("使脉冲、波导、波动和光环类招式\n威力提升30%.确保所有招式无视命\n中判定,必定命中.基础命中率低于\n80%的招式获得-3优先度.");
constexpr u8 __sAbilityText_313837552[] = _("火焰弹在任何超级发射器强化的招\n式后触发一个威力50的一般属性迸\n裂拳.迸裂拳没有追加效果,且攻击\n场上所有周围的宝可梦.");
constexpr u8 __sAbilityText_2135197625[] = _("使用接触类招式时,对目标施加寄\n生种子,每回合结束时吸取目标1/8\n的最大HP.");
constexpr u8 __sAbilityText_659893838[] = _("所有受到的伤害降低20%.与其他减\n伤来源乘法叠加.以威力20的音速\n拳反击接触类招式.");
constexpr u8 __sAbilityText_292978647[] = _("当使用者成功被接触招式命中时,\n在对手场上设置一层撒菱.每层使\n替换上场的接地宝可梦分别损失最\n大HP的12.5%、16.7%或25%（对应\n1-3层）连续攻击招式的每一次命\n中都会设置一层.");
constexpr u8 __sAbilityText_3048257928[] = _("毒棘特性在受到接触招式攻击时,\n自动在对手场上设置一层毒菱.每\n层会使替换上场的接地宝可梦中\n毒：一层为普通中毒,两层为剧毒.\n连续攻击招式的每一次命中都会设\n置一层.");
constexpr u8 __sAbilityText_3036629027[] = _("回旋踢使所有踢腿类招式必定命\n中,并且攻击目标改为对手较弱的\n防御能力值.");
constexpr u8 __sAbilityText_2560460053[] = _("将使用者的一般属性招式变为岩石\n属性.如果使用者是岩石属性,其岩\n石属性招式有10%的几率造成流\n血；否则,它获得岩石属性的本系\n加成.");
constexpr u8 __sAbilityText_1844776739[] = _("当使用者受到任何接触招式攻击\n时,在对手场上设置隐形岩.隐形岩\n在对手替换上场时造成其最大\nHP1/8的伤害.视为岩石属性伤害,\n受属性相性影响.");
constexpr u8 __sAbilityText_2282369846[] = _("旋转陀螺在使用格斗属性招式时,\n使使用者速度提升1级,并移除己方\n场上的所有入场陷阱.");
constexpr u8 __sAbilityText_3148606413[] = _("自动对提升能力的对手使用威力\n150的破坏光线.触发的破坏光线没\n有休息回合,允许下回合正常行动.");
constexpr u8 __sAbilityText_3595368398[] = _("恐惧散布者在出场时降低所有对手\n宝可梦的攻击和特攻1级.此外,使\n用接触类招式命中时,有10%的几率\n造成恐惧.");
constexpr u8 __sAbilityText_1533121065[] = _("王之怒在使用者或其同伴的能力被\n降低时触发,立即提升使用者的攻\n击和防御1级.不会因自身引起的能\n力降低而激活.");
constexpr u8 __sAbilityText_1545459186[] = _("后之哀在使用者或其同伴的能力被\n降低时触发,立即提升使用者的特\n攻和特防1级.不会因自身引起的能\n力降低而激活.");
constexpr u8 __sAbilityText_3055619773[] = _("毒溢特性每回合伤害所有非毒属性\n宝可梦,造成其1/8的HP损失.拥有\n毒疗特性的宝可梦反而会回复.使\n用者下场时效果消失.");
constexpr u8 __sAbilityText_1420109082[] = _("在沙暴生效时,所有同伴免疫异常\n状态和来自敌人的招式追加效果.");
constexpr u8 __sAbilityText_27135183[] = _("将使用者的一般属性招式变为龙属\n性.如果使用者是龙属性,其龙属性\n招式对妖精属性造成普通伤害；否\n则,它获得龙属性的本系加成.");
constexpr u8 __sAbilityText_3000054890[] = _("漂亮公主使使用者对拥有任何负向\n能力等级的目标造成50%额外伤害.");
constexpr u8 __sAbilityText_575764465[] = _("每回合结束时回复1/16的最大HP,\n并且替换下场时治愈所有异常状\n态.");
constexpr u8 __sAbilityText_1105394973[] = _("受到任何招式攻击时,使用者会进\n入充电状态,使下一次电属性招式\n威力加倍.将所有一般属性招式转\n变为电属性招式,并为电属性招式\n提供本系加成.如果使用者是电属\n性,其电属性招式有10%的几率造成\n麻痹.");
constexpr u8 __sAbilityText_4049254121[] = _("火属性招式威力提升30%,当HP低于\n1/3时提升80%.");
constexpr u8 __sAbilityText_429087680[] = _("水属性招式威力提升30%,当HP低于\n1/3时提升80%.");
constexpr u8 __sAbilityText_2871572683[] = _("草属性招式威力提升30%,当HP低于\n1/3时提升80%.");
constexpr u8 __sAbilityText_4170061475[] = _("原始颚使所有啃咬类招式攻击两\n次.第一击造成100%伤害,第二击造\n成40%伤害.每次攻击独立判定追加\n效果（畏缩除外）.");
constexpr u8 __sAbilityText_3838508714[] = _("横扫利刃使所有锐利刀刃类招式必\n定命中,并在双打对战中同时攻击\n双方对手.连续攻击招式对每个目\n标只攻击一次.");
constexpr u8 __sAbilityText_3091754614[] = _("天赋异禀使该宝可梦免疫恶、幽灵\n和虫属性招式,同时其使用的所有\n变化招式必定命中.此免疫效果无\n视奇妙空间.");
constexpr u8 __sAbilityText_1995928828[] = _("水力循环使电属性招式威力提升\n50%,并使用水属性招式时,回复造\n成伤害25%的HP.");
constexpr u8 __sAbilityText_3449400994[] = _("昼夜平分为每次攻击选择较高的进\n攻能力值.如果攻击较高,物理和特\n殊招式都使用攻击能力值；如果特\n攻较高,则都使用特攻能力值.");
constexpr u8 __sAbilityText_4109094813[] = _("吸收特性使吸取类招式的HP回复量\n提升50%,并在命中时对目标施加寄\n生种子,每回合结束时吸取目标1/8\n的最大HP.");
constexpr u8 __sAbilityText_3901843086[] = _("无知的特性在该宝可梦在场时,无\n效化所有天气、场地和房间效果.");
constexpr u8 __sAbilityText_2510212255[] = _("使前两次受到的伤害变为0.招式仍\n会连接且附加效果生效,但伤害变\n为0.");
constexpr u8 __sAbilityText_2709312273[] = _("廉价战术在替换上场时,使用抓\n（40威力,一般属性物理招式）攻\n击随机一名对手.");
constexpr u8 __sAbilityText_2141655576[] = _("懦夫特性在出场时自动激活保护每\n场战斗仅生效一次.");
constexpr u8 __sAbilityText_2718254305[] = _("伏特冲击在该宝可梦HP全满时,赋\n予所有电属性招式+1优先度.");
constexpr u8 __sAbilityText_2851884108[] = _("沙丘恐惧在沙暴中使受到的伤害降\n低35%,并使地面属性招式威力提升\n20%.伤害减免与其他来源乘法叠\n加.");
constexpr u8 __sAbilityText_3932791797[] = _("地狱之怒使火属性招式威力提升\n35%,但使用后会造成5%的反伤.反\n伤基于造成的伤害量计算,最少损\n失1HP.此反伤不会导致使用者濒\n死.");
constexpr u8 __sAbilityText_241482446[] = _("通常只命中一次的超级发射器和锐\n利刀刃类招式现在会攻击两次,每\n次造成招式正常伤害的70%.追加效\n果在每次攻击中独立判定（畏缩除\n外）.");
constexpr u8 __sAbilityText_1265984323[] = _("元素充能使攻击招式有20%的几率\n根据招式属性施加异常状态：电属\n性招式造成麻痹,火属性招式造成\n灼伤,冰属性招式造成冻伤.");
constexpr u8 __sAbilityText_1671714832[] = _("埋伏特性在使用者替换上场后或战\n斗开始的第一回合,必定造成击中\n要害.");
constexpr u8 __sAbilityText_2207751849[] = _("阿特拉斯在进入战斗时设置重力,\n持续8回合.重力防止飞翔等飘浮招\n式,使所有宝可梦接地从而易受地\n面属性招式、沙穴和场地状态影响\n使重力苹果的伤害提升50%,并使招\n式命中率提升66%.");
constexpr u8 __sAbilityText_1894170186[] = _("光辉使使用者的所有招式命中率提\n升20%,并使恶属性招式失效.");
constexpr u8 __sAbilityText_254394259[] = _("使用啃咬类招式击败对手时,回复\n50%最大HP；使用其他招式击败时,\n回复25%.仅当通过直接攻击击倒目\n标时触发.");
constexpr u8 __sAbilityText_3584008191[] = _("撞击进行再来一次+封印,吐丝设置\n所有场地状态,变硬全能力提升1\n级,铁壁变为王者盾牌并降低所有\n能力,电网束缚目标,虫咬回复造成\n的伤害,毒针造成剧毒且对钢属性\n效果绝佳.所有强化后的攻击获得\n大幅伤害加成.");
constexpr u8 __sAbilityText_3839703390[] = _("受到攻击前变为抵抗的属性,攻击\n前变为与招式匹配的属性,物理伤\n害减半,特殊伤害减半.伤害减免与\n其他来源乘法叠加.");
constexpr u8 __sAbilityText_770858237[] = _("电击之颚使所有啃咬类招式在命中\n时有50%的几率使目标陷入麻痹状\n态.连续攻击的每一击都会独立判\n定.");
constexpr u8 __sAbilityText_1537165253[] = _("对妖精属性宝可梦造成1.5倍伤害,\n并且受到妖精属性宝可梦攻击时,\n伤害减半.此效果基于攻击方/防御\n方宝可梦的属性,而非招式属性.伤\n害减免与其他来源乘法叠加.");
constexpr u8 __sAbilityText_3591420234[] = _("在进入战斗时设置重力,持续5回\n合.重力防止飞翔等飘浮招式,使所\n有宝可梦接地从而易受地面属性招\n式、沙穴和场地状态影响,使重力\n苹果的伤害提升50%,并使招式命中\n率提升66%.");
constexpr u8 __sAbilityText_112981844[] = _("蒸发特性使受到的水属性招式伤害\n无效,并在受到水属性招式攻击时,\n为己方场上设置持续5回合的白雾.\n白雾保护全队免受能力降低,包括\n自身引起的降低.");
constexpr u8 __sAbilityText_4271750029[] = _("对草属性宝可梦造成1.5倍伤害,并\n且受到草属性宝可梦攻击时,伤害\n减半.此效果基于攻击方/防御方宝\n可梦的属性,而非招式属性.伤害减\n免与其他来源乘法叠加.");
constexpr u8 __sAbilityText_2723763115[] = _("好烤的身体使该宝可梦免疫火属性\n招式,并在受到火属性攻击时,防御\n能力值提升2级.");
constexpr u8 __sAbilityText_1126751237[] = _("熔炉特性在受到岩石属性招式攻击\n时,或在存在隐形岩的情况下替换\n上场时,速度能力值提升2级.");
constexpr u8 __sAbilityText_1106334732[] = _("受到任何招式攻击时,使用者会进\n入充电状态,使下一次电属性招式\n威力加倍.充电状态在使用一次电\n属性招式后消耗.");
constexpr u8 __sAbilityText_1261232332[] = _("岩石载荷使岩石属性和投掷类招式\n威力提升50%.投掷类招式包括投\n球、投蛋、岩崩、击落、投掷、岩\n石炮、重力苹果和星碎.");
constexpr u8 __sAbilityText_1940518699[] = _("食土特性在受到地面属性招式攻击\n时,为该宝可梦回复其最大HP的\n25%.");
constexpr u8 __sAbilityText_677101954[] = _("余香特性在受到接触招式攻击时,\n将攻击者的特性（非先天特性）改\n变为余香.");
constexpr u8 __sAbilityText_2308666086[] = _("进入战斗时,为使用者的当前属性\n添加妖精属性.即使失去此特性,添\n加的妖精属性在替换下场前依然保\n留.");
constexpr u8 __sAbilityText_857333525[] = _("火属性招式攻击两次,每次造成招\n式正常伤害的70%.追加效果在每次\n攻击中独立判定（畏缩除外）.");
constexpr u8 __sAbilityText_1638677657[] = _("每当使用者通过直接攻击击倒对手\n时,其速度能力值提升1级.");
constexpr u8 __sAbilityText_836738655[] = _("30%几率添加基于属性的效果：毒\n系：剧毒,冰：冻伤,水：混乱,火：\n灼伤,电/超能力/妖精/草:设置对\n应场地,一般:再来一次,岩石:隐形\n岩,幽灵:封印,恶:流血,格斗:+特攻,\n飞行:+速度,龙:-攻击,地面:束缚,钢\n:+防御.");
constexpr u8 __sAbilityText_2905022052[] = _("冰霜占卜将所有招式的冻伤几率乘\n以5倍.与冻结点特性不叠加.");
constexpr u8 __sAbilityText_4264783148[] = _("幻痛特性移除一般属性对幽灵属性\n招式的免疫,允许幽灵属性攻击以1\n倍效果命中一般属性宝可梦.");
constexpr u8 __sAbilityText_4215489656[] = _("幽灵属性招式威力提升30%,当HP低\n于1/3时提升80%.");
constexpr u8 __sAbilityText_90083156[] = _("将使用者的一般属性招式变为超能\n力属性.如果使用者是超能力属性,\n其超能力属性招式有10%的几率造\n成混乱；否则,它获得超能力属性\n的本系加成.");
constexpr u8 __sAbilityText_1965448309[] = _("使威力小于等于60的招式威力提升\n1.5倍.对于基础威力可能超过60的\n招式（如复仇或毒击）,即使当前\n威力小于等于60,也不会获得提升.\n使连续攻击招式必定打出5次.对于\n仅能攻击3次或使用大扫荡时,所有\n攻击进行一次命中判定.");
constexpr u8 __sAbilityText_2992251285[] = _("猴子把戏在替换上场时自动使用挠\n痒,降低对手宝可梦的攻击和防御\n各1级.");
constexpr u8 __sAbilityText_1891108858[] = _("格斗专家使拳类和踢腿类招式的威\n力提升30%.");
constexpr u8 __sAbilityText_2967282293[] = _("丛林守卫保护使用者和草属性同伴\n免受异常状态和能力降低影响,并\n在大晴天时每回合结束时治愈使用\n者的异常状态.");
constexpr u8 __sAbilityText_3542144650[] = _("使角和钻类攻击的威力提升30%.当\n使用者通过直接攻击击倒对手时,\n立即回复其最大HP的25%.");
constexpr u8 __sAbilityText_2629768763[] = _("使用者、其同伴以及对手的所有妖\n精属性招式获得1.33倍的威力提\n升.此加成会被气场破坏反转.所有\n招式获得1.2倍命中率提升.");
constexpr u8 __sAbilityText_3935318675[] = _("等离子灯使火属性和电属性招式的\n威力和命中率各提升20%.");
constexpr u8 __sAbilityText_438808928[] = _("当使用者通过直接攻击击倒对手\n时,立即回复其最大HP的25%.火属\n性招式对岩石属性宝可梦变得效果\n绝佳,而非被抵抗.");
constexpr u8 __sAbilityText_3113056940[] = _("接触类招式有30%几率造成灼伤,并\n且使用者在受到接触类招式攻击\n时,降低攻击者的速度1级.");
constexpr u8 __sAbilityText_1130299248[] = _("拳类招式威力提升30%.水属性招式\n在大晴天时不受威力降低的惩罚.");
constexpr u8 __sAbilityText_1803121217[] = _("弓箭手使箭矢类招式的威力提升\n30%.");
constexpr u8 __sAbilityText_3212495071[] = _("使电属性招式造成灼伤效果,而非\n麻痹.");
constexpr u8 __sAbilityText_74818520[] = _("超级重击者使锤类招式的威力提升\n30%.");
constexpr u8 __sAbilityText_571883735[] = _("加速特性消除了两回合招式的蓄力\n回合要求,使其可以立即使用.");
constexpr u8 __sAbilityText_67624040[] = _("使用任何火属性招式后,立即触发\n一次威力40的冰冻光束.");
constexpr u8 __sAbilityText_3283755841[] = _("发痒防御在使用者成功被接触招式\n命中时,以纠缠不休束缚攻击者.被\n束缚的对手每回合损失1/8的最大\nHP,持续4-5回合,且无法替换下场.");
constexpr u8 __sAbilityText_3808072918[] = _("发电机在替换上场时使使用者进入\n充电状态,下一次电属性招式威力\n加倍.在战斗中电气场地激活时再\n次充电.充电状态在替换下场或使\n用一次电属性招式后消失.");
constexpr u8 __sAbilityText_451682143[] = _("月之魂使所有妖精和恶属性招式获\n得本系加成,无论使用者的属性如\n何.使用月光时,回复量提升至最大\nHP的75%,而非通常的50%或受天气\n影响的数值.");
constexpr u8 __sAbilityText_3502479878[] = _("替换上场时对对手使用泼沙,降低\n其命中率1级.");
constexpr u8 __sAbilityText_2924109087[] = _("受到攻击时,特攻提升1级；受到击\n中要害时,特攻提升至最大.击倒对\n手时,立即从休息状态中恢复,允许\n立即使用破坏光线等招式而无需等\n待.");
constexpr u8 __sAbilityText_3667018789[] = _("出场时使用封印.封印阻止目标使\n用其最后使用的招式,持续4回合.\n如果目标尚未行动,则失败.");
constexpr u8 __sAbilityText_3414675350[] = _("沙之守卫在沙暴中阻挡先制招式,\n并使特殊攻击伤害降低50%.与其他\n减伤来源乘法叠加.");
constexpr u8 __sAbilityText_2620461718[] = _("替换下场时,治愈所有异常状态,并\n回复33%的最大HP.");
constexpr u8 __sAbilityText_669839575[] = _("在顺风状态下进入战斗时,提升使\n用者最高的攻击能力值.受到风类\n招式攻击时,吸收该攻击并使最高\n的攻击能力值提升1级.");
constexpr u8 __sAbilityText_1201646215[] = _("出场时,治愈使用者队伍中所有宝\n可梦（包括场上和后备）的异常状\n态.");
constexpr u8 __sAbilityText_305021358[] = _("受到接触攻击时（无论攻防）,有\n50%几率使攻击者着迷（将其攻击\n和特攻减半）.仅对异性宝可梦生\n效.免疫对手所有提升伤害的特性\n效果,亲子爱和多头龙特性除外.");
constexpr u8 __sAbilityText_354814854[] = _("使用者的招式会造成伤害量25%的\n反伤.当使用者通过直接攻击击倒\n对手时,其攻击能力值降低1级.");
constexpr u8 __sAbilityText_2884225584[] = _("受到攻击时,该宝可梦的特攻提升1\n级；若受到击中要害的攻击,则特\n攻能力值提升至最大.对于连续攻\n击招式,每次命中都会触发.");
constexpr u8 __sAbilityText_1146809047[] = _("将所有一般属性招式转变为超能力\n属性,并为超能力属性招式提供本\n系加成,无论使用者的属性如何.真\n气弹必定命中.不受畏缩、威吓或\n惊吓的影响.");
constexpr u8 __sAbilityText_427740537[] = _("美梦特性在使用者处于睡眠状态或\n拥有绝对睡眠特性时,每回合结束\n时回复1/8的最大HP.此外,它免疫\n梦魇特性的伤害.每回合结束时回\n复1/16的最大HP.");
constexpr u8 __sAbilityText_525879731[] = _("在使用造成伤害的招式命中后,使\n用者紧接着使用震级,威力为10、\n30、50或70.攻击所有相邻的宝可\n梦.");
constexpr u8 __sAbilityText_1589840349[] = _("与该宝可梦发生接触有20%几率造\n成冻伤.非接触攻击有30%几率.无\n论攻击方还是被攻击方均会生效.\n冻伤的宝可梦每回合损失1/8的最\n大HP,且特攻减半.");
constexpr u8 __sAbilityText_4210150605[] = _("与该宝可梦发生接触有30%几率造\n成冻伤.非接触攻击有20%几率.无\n论攻击方还是被攻击方均会生效.\n冻伤的宝可梦每回合损失1/8的最\n大HP,且特攻减半.受到攻击后设置\n冰雹.免疫冰雹伤害.");
constexpr u8 __sAbilityText_2887146400[] = _("使所有招式获得1.5倍的本系加成,\n无论属性是否匹配.不会增强已经\n获得本系加成的招式.此外,效果绝\n佳的招式威力提升10%.");
constexpr u8 __sAbilityText_2036328944[] = _("出场时使用破灭之愿.破灭之愿是\n钢属性招式,基础威力140,两回合\n后攻击目标,可穿透替身和其他保\n护效果.一旦施放必定命中,无视命\n中判定.无法对同一目标施放两次.");
constexpr u8 __sAbilityText_2452418660[] = _("出场时使用祈愿,设置延迟治疗,在\n下回合为当前同伴回复其最大HP的\n一半.每场战斗可激活3次.");
constexpr u8 __sAbilityText_1549646636[] = _("出场时降低所有对手宝可梦的攻击\n和特攻1级.此外,接触攻击时有30%\n几率使目标着迷（将其攻击和特攻\n减半）.无论攻击方还是被攻击方\n均会生效.仅对异性宝可梦生效.");
constexpr u8 __sAbilityText_166022989[] = _("出场时使用无理取闹,阻止对手连\n续使用相同的招式.");
constexpr u8 __sAbilityText_1596183019[] = _("受到效果绝佳的招式攻击时,伤害\n降低35%.与其他减伤来源乘法叠\n加.使使用者的招式命中率提升1.2\n倍.攻击命中时,移除目标的幽灵属\n性.");
constexpr u8 __sAbilityText_3409492718[] = _("确保亚空裂斩总是造成击中要害,\n并使所有其他招式的击中要害率提\n升1级.");
constexpr u8 __sAbilityText_1501854346[] = _("出场时制造水流环,每回合回复\n1/16的HP.免疫灼伤状态,并在替换\n上场时解除灼伤.下雨天气时,每回\n合结束时治愈所有异常状态.");
constexpr u8 __sAbilityText_1385212222[] = _("出场时降下雨水,持续8回合.下雨\n天气时,使用者的速度提升50%.");
constexpr u8 __sAbilityText_1039384634[] = _("在使用水属性攻击（包括浸水等变\n化招式）命中后,触发一次威力50\n的冲浪.冲浪攻击所有相邻的宝可\n梦.");
constexpr u8 __sAbilityText_903681105[] = _("出场时使用心灵互换.与正对面的\n宝可梦交换能力等级无视命中判\n定.");
constexpr u8 __sAbilityText_3592011986[] = _("锐利刀刃类招式变为特殊（造成特\n殊伤害并使用特攻能力值）,并造\n成30%额外伤害.");
constexpr u8 __sAbilityText_833719679[] = _("当该宝可梦处于任何异常状态时,\n其特攻能力值提升50%.同时防止冻\n伤状态降低特攻.");
constexpr u8 __sAbilityText_3171872008[] = _("将使用者的一般属性招式变为草属\n性.如果使用者是草属性,其草属性\n招式会回复造成伤害10%的HP；否\n则,它获得草属性的本系加成.");
constexpr u8 __sAbilityText_3124988848[] = _("接触攻击时有50%几率使目标着迷\n（将其攻击和特攻减半）.攻击着\n迷的目标时,回复造成伤害25%的\nHP.");
constexpr u8 __sAbilityText_1659869559[] = _("格斗属性招式威力提升20%,当HP低\n于1/3时提升50%.");
constexpr u8 __sAbilityText_1428912407[] = _("允许变化招式穿透所有免疫和属性\n抗性,但会强制其在当前优先度层\n级内最后行动.");
constexpr u8 __sAbilityText_2571486295[] = _("出场时使用念动力.所有针对目标\n的招式不会打空,但目标会免疫地\n面属性招式和其他需要接地的效\n果.对扎根或携带黑色铁球的宝可\n梦无效.在重力下或被击落命中后\n失效.持续3回合.");
constexpr u8 __sAbilityText_3827464519[] = _("燃烧使所有火属性招式的威力提升\n50%.");
constexpr u8 __sAbilityText_3055217817[] = _("锐利刀刃类招式变为特殊（造成特\n殊伤害并使用特攻能力值）,并造\n成30%额外伤害.并且为锐利刀刃类\n招式再提供30%威力加成.");
constexpr u8 __sAbilityText_311846083[] = _("出场时使用粉尘,在本回合内覆盖\n目标.如果被覆盖的目标使用任何\n火属性招式,其损失25%的最大HP,\n且粉尘被消耗.");
constexpr u8 __sAbilityText_2891241594[] = _("替换下场时,如果未携带物品,则取\n回原本携带的物品.必须在未濒死\n时才能激活.");
constexpr u8 __sAbilityText_3221720298[] = _("出场时使用不给糖就捣蛋,为目标\n添加幽灵属性.目标不会从雾中受\n益.效果持续到目标替换下场.");
constexpr u8 __sAbilityText_424822424[] = _("在使用舞蹈类招式后,自动接续一\n次威力50的启示之舞.后续的启示\n之舞属性与使用者的首要属性一\n致.");
constexpr u8 __sAbilityText_3049266850[] = _("怨恨特性在受到接触招式攻击时,\n减少攻击者最后使用招式的PP4点.\n如果攻击者已无PP或尚未使用任何\n招式,则失败.");
constexpr u8 __sAbilityText_4154106896[] = _("受到攻击时,该宝可梦的特防提升1\n级；若受到击中要害的攻击,则特\n防能力值提升至最大.对于连续攻\n击招式,每次命中都会触发.");
constexpr u8 __sAbilityText_2746177153[] = _("使啃咬类招式威力提升30%.所有啃\n咬类招式攻击两次.第一击造成\n100%伤害,第二击造成40%伤害.每\n次攻击独立判定追加效果.");
constexpr u8 __sAbilityText_1730209432[] = _("替换上场时,使用威力40的幽灵窃\n贼（幽灵属性招式）攻击正对面的\n对手.窃取目标所有的正向能力提\n升（在造成伤害前）,并将其赋予\n使用者.必定命中且无视替身.");
constexpr u8 __sAbilityText_1243518255[] = _("当HP全满时,幽灵属性招式获得+1\n优先度.");
constexpr u8 __sAbilityText_2885597666[] = _("束缚类招式持续6回合而非4-5回\n合,并且每回合结束时的伤害提升\n至目标最大HP的1/6.");
constexpr u8 __sAbilityText_601903330[] = _("使声音类招式威力提升30%.单体目\n标的声音类招式变为范围攻击,同\n时攻击双方对手.连续攻击招式不\n会变为范围攻击同时使使用者的声\n音类招式再获得30%威力提升,并使\n受到的声音类招式伤害降低50%.伤\n害减免与其他来源乘法叠加.");
constexpr u8 __sAbilityText_3762373939[] = _("啃咬类招式在命中时有50%的几率\n使目标灼伤.连续攻击的每一击都\n会独立判定.");
constexpr u8 __sAbilityText_2751904173[] = _("对恶属性宝可梦造成1.5倍伤害,并\n且受到恶属性宝可梦攻击时,伤害\n减半.此效果基于攻击方/防御方宝\n可梦的属性,而非招式属性.伤害减\n免与其他来源乘法叠加.");
constexpr u8 __sAbilityText_2031117131[] = _("替换上场时,攻击提升1级.受到攻\n击时,攻击提升1级；受到击中要害\n时,攻击提升至最大.对于连续攻击\n招式,每次命中都会触发.");
constexpr u8 __sAbilityText_2648217082[] = _("替换上场时,防御提升1级.受到攻\n击时,防御提升1级；受到击中要害\n时,防御提升至最大.对于连续攻击\n招式,每次命中都会触发.");
constexpr u8 __sAbilityText_1091004561[] = _("出场时,使用者最高的攻击能力值\n提升2级,但会陷入愤怒,所有攻击\n附加33%的反伤.即使无法陷入愤\n怒,能力提升依然生效.");
constexpr u8 __sAbilityText_3401217372[] = _("阻止所有对手宝可梦消耗其携带的\n物品.当使用者通过直接攻击击倒\n对手时,其攻击和特攻能力值各提\n升1级.");
constexpr u8 __sAbilityText_1248751110[] = _("当使用者受到接触招式攻击时,以\n威力50的夹住进行反击.这个钢属\n性招式会束缚对手4-5回合,每回合\n造成其1/8的最大HP伤害.");
constexpr u8 __sAbilityText_1929974947[] = _("阻止所有对手宝可梦通过任何方式\n回复HP.阻挡回复类招式如自我再\n生,吸取类招式如吸取拳,剩饭等被\n动回复和再生力等特性,并阻止树\n果和其他物品的HP回复.");
constexpr u8 __sAbilityText_2393571604[] = _("每当使用者通过直接攻击击倒对手\n时,其特攻能力值提升1级.");
constexpr u8 __sAbilityText_3453272996[] = _("对处于混乱或愤怒状态的目标,攻\n击造成双倍伤害.此外,混乱或愤怒\n的敌人因此状态伤害自身时,受到\n的伤害也加倍.");
constexpr u8 __sAbilityText_1106638732[] = _("心眼允许一般属性和格斗属性招式\n以普通效果命中幽灵属性宝可梦.\n此外,此特性防止使用者的命中率\n被对手的招式或特性降低.");
constexpr u8 __sAbilityText_372892935[] = _("血价使所有攻击招式威力提升30%,\n但使用者在攻击命中时损失其最大\nHP的10%.");
constexpr u8 __sAbilityText_1245565174[] = _("尖刺盔甲无论攻击方还是被攻击\n方,在使用接触类招式时有30%的几\n率造成流血.流血每回合造成1/16\n最大HP伤害,阻止回复,并使能力等\n级效果无效.岩石和幽灵属性免疫\n流血.");
constexpr u8 __sAbilityText_444797924[] = _("铬涂层使受到的特殊伤害降低40%,\n但速度降低10%.同时使使用者的重\n量变为3倍.伤害减免与其他来源乘\n法叠加.");
constexpr u8 __sAbilityText_1712827778[] = _("使所有声音类招式的威力提升20%,\n并将一般属性的声音类招式转变为\n幽灵属性.");
constexpr u8 __sAbilityText_3174028905[] = _("替换上场时使用吐丝,大幅降低所\n有对手的速度2级.");
constexpr u8 __sAbilityText_2256768547[] = _("替换上场后的一回合内,必定造成\n击中要害,同时攻击提升20%,速度\n提升50%.");
constexpr u8 __sAbilityText_816783598[] = _("当该宝可梦受到直接攻击伤害时,\n激活青草场地,持续5回合（携带场\n地制造机时为8回合）.同时治愈己\n方所有宝可梦的异常状态.");
constexpr u8 __sAbilityText_3505951297[] = _("在战斗中使使用者及其同伴的飞行\n属性招式威力提升30%.");
constexpr u8 __sAbilityText_2821801825[] = _("当场上任何宝可梦使用声音类招式\n后,该宝可梦会立即使用相同的招\n式每回合对每个招式触发一次.");
constexpr u8 __sAbilityText_2775480767[] = _("当使用者进入战斗时,阻止所有对\n手宝可梦逃跑或替换效果持续到使\n用者下场.强制替换和快速折返等\n替换招式仍然有效.");
constexpr u8 __sAbilityText_1987847335[] = _("免疫所有异常状态.此外,受到的幽\n灵属性伤害降低50%.如果在获得此\n特性时已处于异常状态,则立即治\n愈.");
constexpr u8 __sAbilityText_3321357103[] = _("在大晴天下,使用者最高的能力值\n提升（速度提升50%,其他提升\n30%）.大晴天结束时,如果携带驱\n劲能量则激活.此效果视为原始能\n力提升而非能力等级变化.除非被\n单纯光束或烦恼种子影响,否则无\n法被复制、压制或替换.");
constexpr u8 __sAbilityText_3193196292[] = _("在电气场地中,使用者最高的能力\n值提升（速度提升50%,其他提升\n30%）.场地结束时,如果携带驱劲\n能量则激活.此效果视为原始能力\n提升而非能力等级变化.除非被单\n纯光束或烦恼种子影响,否则无法\n被复制、压制或替换.");
constexpr u8 __sAbilityText_1247245396[] = _("受到基于风的招式攻击或在顺风中\n进入战斗时,获得充电状态.充电状\n态使下一次电属性招式威力加倍,\n直到使用为止.");
constexpr u8 __sAbilityText_2691926134[] = _("非接触类招式使用速度能力值而非\n攻击/特攻进行伤害计算.讲究围巾\n的效果不影响此特性.");
constexpr u8 __sAbilityText_1888075818[] = _("使用非接触类招式时,将使用者20%\n的速度能力值加入伤害计算.讲究\n围巾的效果不影响此特性.");
constexpr u8 __sAbilityText_3102760299[] = _("看门狗防止因招式或红牌被强制替\n换.受到威吓或惊吓影响时,改为提\n升相应能力1级而非降低.");
constexpr u8 __sAbilityText_3913285408[] = _("当HP降至50%以下时,使用者触发破\n壳效果：攻击、特攻和速度各提升\n2级,同时防御和特防各降低1级.每\n场战斗仅触发一次.在连续攻击的\n最后一击后触发.");
constexpr u8 __sAbilityText_1047428267[] = _("利己主义者复制敌人宝可梦获得的\n能力提升,并应用于自身.不会复制\n其他利己主义者的增益.");
constexpr u8 __sAbilityText_3934055176[] = _("使招式造成的能力降低效果加倍不\n影响自身引起的能力降低或敌人的\n特性.");
constexpr u8 __sAbilityText_1023753186[] = _("使用者的攻击能力值在上场的第一\n回合变为2倍.与其他伤害加成效果\n乘法叠加.替换下场后再次上场可\n重新触发.");
constexpr u8 __sAbilityText_227696856[] = _("当HP全满时,赋予恶属性招式+1优\n先度.");
constexpr u8 __sAbilityText_4197039073[] = _("给予使用者最后一击的攻击者,其\n攻击和特攻降低2级.仅当因直接伤\n害而濒死时生效.");
constexpr u8 __sAbilityText_3021520790[] = _("当HP全满时,赋予水属性招式+1优\n先度.");
constexpr u8 __sAbilityText_3746804508[] = _("替换下场后,再次上场时变身为英\n雄形态,持续到战斗结束.无法被压\n制、交换、复制或覆盖.");
constexpr u8 __sAbilityText_3619223761[] = _("在双打对战中替换上场时,同台共\n演复制同伴的所有能力等级变化\n（包括正向和负向）.");
constexpr u8 __sAbilityText_116155853[] = _("允许米立龙进入同伴吃吼霸体内并\n变得无法被选中.吃吼霸获得全能\n力+2,无法替换或被强制替换,同时\n米立龙变得无法使用.如果吃吼霸\n濒死,米立龙重新出现并可正常行\n动.无法被交换、复制或压制.");
constexpr u8 __sAbilityText_2757261547[] = _("当使用者的任何能力被降低时（包\n括自身引起的能力降低）,自动替\n换下场.每场战斗触发一次.");
constexpr u8 __sAbilityText_1303772899[] = _("当被直接攻击击倒时,对攻击者施\n加诅咒.诅咒每回合造成其最大\nHP25%的伤害,直到被诅咒的宝可梦\n替换下场或濒死.幽灵属性的攻击\n者免疫此诅咒.幽灵属性招式威力\n提升30%,当HP低于1/3时提升50%.");
constexpr u8 __sAbilityText_792242812[] = _("消耗树果时,使用者在下一回合结\n束时再次食用该树果.");
constexpr u8 __sAbilityText_2444128419[] = _("防止使用者和它的同伴成为优先度\n大于0的先制招式的目标.");
constexpr u8 __sAbilityText_312129539[] = _("啃咬类招式使用特攻能力值进行伤\n害计算（除非另有说明,否则仍攻\n击目标的防御）,并造成30%额外伤\n害.");
constexpr u8 __sAbilityText_3082361781[] = _("己方每有一只濒死的同伴,攻击和\n特攻提升10%,最多5只同伴可使两\n项能力各提升50%.与其他伤害加成\n效果加法叠加.");
constexpr u8 __sAbilityText_2817873640[] = _("恶意特性会消耗击败使用者的招式\n的PP.必须是直接攻击.");
constexpr u8 __sAbilityText_1531367725[] = _("使用者替换上场后的第一回合,获\n得50%的速度加成和20%的特攻加\n成.");
constexpr u8 __sAbilityText_2199813783[] = _("对使用接触类招式的攻击者造成其\n最大HP1/6的伤害.对于连续攻击招\n式,每次命中都会触发.");
constexpr u8 __sAbilityText_824914763[] = _("受到火属性招式攻击时,攻击提升1\n级,并且免疫灼伤状态.攻击提升在\n受到火属性攻击的伤害后立即生\n效.对于连续攻击招式,每次命中都\n会触发.");
constexpr u8 __sAbilityText_3720729070[] = _("黄金之躯免疫所有直接以该宝可梦\n为目标的变化招式.但仍会受到影\n响全场的黑雾等变化招式影响.");
constexpr u8 __sAbilityText_3961669957[] = _("场上所有宝可梦的能力变化（正向\n和负向）都会在彼此间共享.");
constexpr u8 __sAbilityText_2741602213[] = _("在使用者在场时,降低所有其他宝\n可梦的攻击能力值25%.多个相同的\n灾祸特性效果不叠加与攻击降低效\n果乘法叠加.");
constexpr u8 __sAbilityText_3279187591[] = _("在使用者在场时,降低所有其他宝\n可梦的防御能力值25%.多个相同的\n灾祸特性效果不叠加与防御降低效\n果乘法叠加.");
constexpr u8 __sAbilityText_1530540065[] = _("在使用者在场时,降低所有其他宝\n可梦的特攻能力值25%.多个相同的\n灾祸特性效果不叠加与特攻降低效\n果乘法叠加.");
constexpr u8 __sAbilityText_2058714163[] = _("在使用者在场时,降低所有其他宝\n可梦的特防能力值25%.多个相同的\n灾祸特性效果不叠加与特防降低效\n果乘法叠加.");
constexpr u8 __sAbilityText_2499298466[] = _("使第一次受到的伤害变为0.招式仍\n会连接且附加效果生效,但伤害变\n为0.");
constexpr u8 __sAbilityText_4029585304[] = _("出场时降下大晴天,持续8回合（携\n带炎热岩石时为12回合）.在大晴\n天下,使用者的攻击能力值提升\n33%.");
constexpr u8 __sAbilityText_1214760762[] = _("在晴天时，阻挡先制招式，\n且受到的物理攻击伤害减半。\n与其他伤害减免相乘。");
constexpr u8 __sAbilityText_511817492[] = _("效果绝佳的攻击威力提升33%.");
constexpr u8 __sAbilityText_1462589920[] = _("出场时制造电气场地,持续8回合\n（携带场地制造机时为12回合）.\n在电气场地上,使用者的特攻能力\n值提升33%.");
constexpr u8 __sAbilityText_1372350212[] = _("在大晴天下,水属性招式获得通常\n只在雨天才有的威力提升.在雨天\n下,火属性招式获得通常只在晴天\n才有的威力提升.");
constexpr u8 __sAbilityText_2145140754[] = _("使所有锐利刀刃类招式必定命中,\n并在双打对战中同时攻击双方对\n手.连续攻击招式对每个目标只攻\n击一次.同时使锐利刀刃类招式威\n力提升30%.");
constexpr u8 __sAbilityText_2779579341[] = _("在薄雾场地中,每回合结束时回复\n使用者最大HP的1/12.");
constexpr u8 __sAbilityText_4223350816[] = _("招式每有一个健康的队伍成员（最\n多6次）,就额外攻击一次.处于濒\n死或异常状态的成员不计数.第一\n击造成全额伤害,每次额外攻击造\n成10%伤害.每次攻击独立判定追加\n效果.");
constexpr u8 __sAbilityText_469446407[] = _("锐利刀刃类招式威力提升30%,并有\n20%的几率在命中时造成灼伤.");
constexpr u8 __sAbilityText_3830074500[] = _("攻击有20%的几率造成畏缩.通过直\n接攻击击败敌人时,使用者获得+1\n速度.");
constexpr u8 __sAbilityText_3379797372[] = _("防止使用者和它的同伴成为声音类\n招式的目标.");
constexpr u8 __sAbilityText_2472632681[] = _("使用声音类招式命中后,有20%几率\n封印目标最后使用的招式,持续4回\n合.");
constexpr u8 __sAbilityText_3080624352[] = _("使所有以使用者为目标的单体招式\n的命中率降低20%.热风等范围招式\n保持正常命中率.");
constexpr u8 __sAbilityText_1218021544[] = _("替换上场时,降低所有对手宝可梦\n最高的进攻能力（攻击或特攻）和\n最高的防御能力（防御或特防）各\n1级.");
constexpr u8 __sAbilityText_3250595261[] = _("使用者的攻击能力值提升50%,并且\n接触类招式有20%的几率施加诅咒.\n诅咒每回合造成目标最大HP25%的\n伤害,直到被诅咒的宝可梦替换下\n场或濒死.攻击提升与其他伤害加\n成效果乘法叠加.");
constexpr u8 __sAbilityText_3459504431[] = _("确保该宝可梦使用的所有招式以及\n所有对该宝可梦使用的招式必定命\n中.龙属性招式被视为拳类招式.");
constexpr u8 __sAbilityText_966779065[] = _("箭矢类招式变为特殊（造成特殊伤\n害并使用特攻能力值）,并造成30%\n额外伤害.");
constexpr u8 __sAbilityText_2331431845[] = _("替换上场时,移除任何激活的场地,\n并获得能力提升：移除青草或电气\n场地时,防御+1；移除薄雾、精神\n或剧毒场地时,特防+1.");
constexpr u8 __sAbilityText_3322681080[] = _("当青草场地激活时,草属性招式威\n力提升50%.");
constexpr u8 __sAbilityText_3081776019[] = _("出场时引发沙暴,持续8回合（携带\n光滑岩石时为12回合）.在沙暴中,\n使用者的地面属性招式可以穿透免\n疫,以普通效果命中飘浮的宝可梦.\n使用者免疫沙暴伤害.");
constexpr u8 __sAbilityText_3086129763[] = _("进行伤害计算时,完全无视对手的\n所有能力等级变化.当该宝可梦的\n能力被其他宝可梦降低时,其攻击\n能力提升2级.");
constexpr u8 __sAbilityText_2723523763[] = _("该宝可梦免疫地面属性招式以及其\n他地面效果,如撒菱和场地状态.飞\n行属性招式伤害提升25%.此外,飞\n行属性招式威力再提升20%,当HP低\n于1/3时提升50%.");
constexpr u8 __sAbilityText_3893494723[] = _("当HP全满时,所有对该宝可梦的攻\n击都将造成效果不好的伤害,无论\n属性相性如何.与其他类似特性不\n同,此效果在连续攻击的每次命中\n都会激活.");
constexpr u8 __sAbilityText_2555529525[] = _("使用者在使用任何招式命中后,有\n30%的几率使目标陷入剧毒连续攻\n击的每一击都会独立判定.");
constexpr u8 __sAbilityText_4172429721[] = _("出场时获得寄生孢子.每回合,受影\n响的宝可梦损失1/8最大HP（幽灵\n属性免疫）.使用接触招式时,将孢\n子传播给目标.孢子持续到替换下\n场.");
constexpr u8 __sAbilityText_4108106252[] = _("当使用者施加中毒时,也同时施加\n混乱.不会因毒菱而触发.");
constexpr u8 __sAbilityText_4233282310[] = _("当使用者使对手混乱时,如果对手\n是异性,则也使其着迷（将其攻击\n和特攻减半）.");
constexpr u8 __sAbilityText_1319000361[] = _("出场时使用延后.延后使大多数改\n变速度的效果无效,包括顺风、戏\n法空间、正向优先度、速度能力提\n升等.负向优先度正常工作.持续5\n回合.");
constexpr u8 __sAbilityText_2660096246[] = _("所有受到的物理攻击伤害减半.与\n其他减伤来源乘法叠加.同时免疫\n所有非攻击性的伤害来源,包括入\n场陷阱、天气伤害、异常状态以及\n反伤伤害.");
constexpr u8 __sAbilityText_4219555328[] = _("当该宝可梦被击倒时,使用威力100\n的大爆炸或迸裂拳（取两者中威力\n更高者）.使用爆炸类招式时,必定\n使目标畏缩.受到任何火属性或飞\n行属性招式攻击时,防御和特防能\n力值各提升1级.对于连续攻击招\n式,每次命中都会触发.能力提升效\n果在攻击命中后生效.");
constexpr u8 __sAbilityText_542681160[] = _("啃咬类招式威力提升30%,并在命中\n时有50%的几率使目标灼伤.连续攻\n击的每一击都会独立判定.");
constexpr u8 __sAbilityText_2973801112[] = _("使用者的攻击能力值在一回合内变\n为2倍,击破屏障,并无视保护效果.\n与其他伤害加成效果乘法叠加.替\n换下场后再次上场可重新触发.");
constexpr u8 __sAbilityText_3267931208[] = _("岩石属性招式威力提升20%,当HP低\n于1/3时提升50%.");
constexpr u8 __sAbilityText_3709779967[] = _("无论攻击方还是被攻击方,使用接\n触类招式时有30%的几率造成混乱.");
constexpr u8 __sAbilityText_307490842[] = _("出场时召唤诡异迷雾,持续8回合\n（携带烟雾球时为12回合）.迷雾\n每回合减少非幽灵/超能力属性宝\n可梦的1级能力提升,使基于天气的\n回复效果减半,给予幽灵/超能力属\n性宝可梦20%的伤害减免,并将所有\n诅咒转变为幽灵属性的诅咒.");
constexpr u8 __sAbilityText_3170573905[] = _("如果使用者是草属性,其受到的火\n属性攻击伤害减半,并且使用草属\n性招式对火属性宝可梦造成2倍伤\n害.伤害减免与其他来源乘法叠加.\n使水属性招式获得本系加成,无论\n使用者的属性如何.同时免疫浸水\n状态.");
constexpr u8 __sAbilityText_4151445630[] = _("在迷雾中时,该宝可梦最高的攻击\n能力值提升50%.");
constexpr u8 __sAbilityText_99390849[] = _("声音类招式在命中时有50%的几率\n使目标着迷（将其攻击和特攻减\n半）.");
constexpr u8 __sAbilityText_3374092947[] = _("在迷雾中,以惊吓反击优先度招式.\n惊吓是威力40的幽灵属性攻击,拥\n有+3优先度且必定造成畏缩此能\n力会在对手的优先度招式使出前激\n活.");
constexpr u8 __sAbilityText_506879776[] = _("使所有声音类招式的威力提升20%,\n并将一般属性的声音类招式转变为\n冰属性.");
constexpr u8 __sAbilityText_2744288039[] = _("在迷雾中进入战斗时,使使用者最\n高的能力值提升1级.");
constexpr u8 __sAbilityText_3451701541[] = _("声音类招式在命中时有50%的几率\n造成流血.流血每回合造成1/16最\n大HP伤害,阻止回复,并使能力等级\n效果无效.岩石和幽灵属性免疫流\n血.");
constexpr u8 __sAbilityText_678345373[] = _("在迷雾中,该宝可梦的速度能力值\n提升50%.");
constexpr u8 __sAbilityText_1788419036[] = _("当HP全满时,赋予妖精属性招式+1\n优先度.");
constexpr u8 __sAbilityText_3006573460[] = _("在迷雾激活时濒死后,当派出下一\n只宝可梦时,使用者以25%的最大HP\n复活即使使用者是在迷雾的最后一\n回合濒死,此效果仍会激活.");
constexpr u8 __sAbilityText_647184503[] = _("无论攻击方还是被攻击方,使用接\n触类招式时有30%的几率造成恐惧.\n恐惧束缚目标2回合,使其受到的伤\n害增加50%.如果被吹飞等招式强制\n替换,目标会摆脱恐惧.");
constexpr u8 __sAbilityText_1073211463[] = _("该宝可梦的招式命中率变为1.2倍,\n且打雷必定命中.");
constexpr u8 __sAbilityText_4199663094[] = _("进入战斗时,降低所有对手宝可梦\n的特攻能力值2级.");
constexpr u8 __sAbilityText_1997909663[] = _("受到接触招式攻击时,使用者以威\n力60的冰锥进行反击.冰锥有20%的\n几率造成畏缩.");
constexpr u8 __sAbilityText_4216392669[] = _("防御和特防能力值随HP降低线性提\n升.倍率从HP全满时的1.0倍提升至\nHP0%时的1.6倍.HP50%时提供1.3倍\n加成,HP25%时提供1.45倍加成.");
constexpr u8 __sAbilityText_2444683005[] = _("使火属性招式对岩石属性宝可梦变\n得效果绝佳,而非被抵抗.使毒属性\n招式对钢属性宝可梦变得效果绝\n佳.此外,该宝可梦可以使任何属性\n的宝可梦陷入中毒状态.");
constexpr u8 __sAbilityText_3449726425[] = _("免疫流血状态.当该宝可梦成功使\n对手流血时,也使其陷入恐惧.恐惧\n束缚目标2回合,使其受到的伤害增\n加50%.如果被吹飞等招式强制替\n换,目标会摆脱恐惧.");
constexpr u8 __sAbilityText_3447913274[] = _("使每只宝可梦的击中要害率提升2\n级.包括同伴和对手.");
constexpr u8 __sAbilityText_360391110[] = _("免疫流血状态.当该宝可梦成功使\n对手流血时,也使其陷入恐惧.恐惧\n束缚目标2回合,使其受到的伤害增\n加50%.如果被吹飞等招式强制替\n换,目标会摆脱恐惧.通过直接攻击\n击倒对手时,回复25%的最大HP.");
constexpr u8 __sAbilityText_1001120324[] = _("使用声音类招式命中时,使用者造\n成流血.流血每回合造成1/16最大\nHP伤害,阻止回复,并使能力等级效\n果无效.岩石和幽灵属性免疫流血.");
constexpr u8 __sAbilityText_2023163105[] = _("连续使用同一招式,每次伤害提高\n10%.无上限.切换招式或招式失败\n时重置.");
constexpr u8 __sAbilityText_2695144209[] = _("在使用任何声音类招式命中后,使\n用者紧接着使用威力40的地震,攻\n击所有相邻的宝可梦.");
constexpr u8 __sAbilityText_1422498706[] = _("锤类招式攻击两次,每次造成招式\n正常伤害的70%.追加效果在每次攻\n击中独立判定（畏缩除外）.");
constexpr u8 __sAbilityText_1214758136[] = _("使用锤类攻击命中时,降低目标防\n御1级.每个目标每回合只能被影响\n一次防御降低在伤害之后生效.");
constexpr u8 __sAbilityText_179520196[] = _("在冰雹中,冰属性招式攻击两次,两\n次均造成全额伤害.使用者免疫冰\n雹伤害.两次攻击独立判定追加效\n果（畏缩除外）.");
constexpr u8 __sAbilityText_2646415407[] = _("锤类招式获得10%的伤害加成,并且\n伤害计算时目标改为特防而非防\n御.");
constexpr u8 __sAbilityText_190549439[] = _("当使用者攻击时,接触目标有50%的\n几率使其麻痹.当受到伤害时,有\n50%的几率使攻击者灼伤.");
constexpr u8 __sAbilityText_3058779840[] = _("使角和钻类攻击的威力提升30%.将\n一般属性招式转变为妖精属性并获\n得妖精属性本系加成.如果使用者\n是妖精属性,其妖精属性招式有10%\n的几率造成着迷.");
constexpr u8 __sAbilityText_1555992663[] = _("在使用者上场的第一回合,所有优\n先度为0或更高的招式获得+1优先\n度.负向优先度招式变为优先度0,\n而非获得+1.");
constexpr u8 __sAbilityText_3278925933[] = _("每当使用者通过直接攻击击倒对手\n时,其击中要害率提升1级.");
constexpr u8 __sAbilityText_2587712159[] = _("所有物理招式威力提升20%,并且接\n触时有20%的几率造成灼伤或中毒.");
constexpr u8 __sAbilityText_4254179722[] = _("在薄雾场地中,每回合结束时回复\n使用者最大HP的1/12.替换下场时,\n回复33%的最大HP.此回复效果不受\n回复封锁影响.");
constexpr u8 __sAbilityText_1366711796[] = _("当消耗或失去携带的物品时,该宝\n可梦的基础速度能力值变为2倍.当\n替换下场、获得新物品或失去此特\n性时,速度加成消失.使所有树果的\n有益效果加倍.");
constexpr u8 __sAbilityText_2562980079[] = _("在迷雾中时,每回合结束时回复使\n用者最大HP的1/8.");
constexpr u8 __sAbilityText_7307171[] = _("无论该宝可梦是攻击方还是被攻击\n方,都有几率使对手陷入麻痹.非接\n触攻击有10%几率麻痹,接触攻击有\n30%几率麻痹.在迷雾中时,每回合\n结束时回复使用者最大HP的1/8.");
constexpr u8 __sAbilityText_811772798[] = _("迷雾使以使用者为目标的招式命中\n率降低25%.");
constexpr u8 __sAbilityText_3087454099[] = _("当敌人试图替换下场时,自动触发\n威力20的追打以防止其离开.");
constexpr u8 __sAbilityText_1017437934[] = _("使所有声音类招式的威力提升20%,\n并将一般属性的声音类招式转变为\n钢属性.");
constexpr u8 __sAbilityText_159361669[] = _("锐利刀刃类招式获得30%的伤害加\n成,并且伤害计算时目标改为特防\n而非防御.");
constexpr u8 __sAbilityText_1922729565[] = _("所有钢属性招式转变为电属性,并\n获得10%的威力提升.");
constexpr u8 __sAbilityText_2378036526[] = _("所有受到的伤害降低20%.与其他减\n伤来源乘法叠加.以威力20的真空\n波反击接触类招式.");
constexpr u8 __sAbilityText_2609750125[] = _("真气弹必定命中.不受畏缩、威吓\n或惊吓的影响.当该宝可梦因对手\n的攻击而使HP降至一半或以下时,\n其最高的攻击能力值提升1级.每场\n战斗仅触发一次.其他伤害来源使\nHP降至一半或以下不会触发此特\n性.");
constexpr u8 __sAbilityText_3989812618[] = _("拥有提升优先度（+1或更高）的\n招式获得20%的伤害加成.");
constexpr u8 __sAbilityText_618294245[] = _("免疫火属性和水属性招式.受到火\n属性招式攻击时,自身该类招式威\n力提升50%,直到下场.受到水属性\n招式攻击时,回复最大HP的25%.");
constexpr u8 __sAbilityText_312674543[] = _("出场时引发冰雹,持续8回合（携带\n冰冷岩石时为12回合）.冰雹每回\n合对非冰属性宝可梦造成1/16的HP\n伤害,并使场上冰属性宝可梦的防\n御提升50%.所有招式的冻伤几率变\n为5倍.与冻结点特性不叠加.");
constexpr u8 __sAbilityText_399824592[] = _("每次攻击前,该宝可梦的属性会变\n为与所用招式相同的属性.每回合\n结束时,该宝可梦有30%的几率治愈\n自身所受到的异常状态.");
constexpr u8 __sAbilityText_3172692085[] = _("当HP首次降至一半或以下时,所有\n能力提升1级,且使用者无法替换或\n逃走.常规的绕过此效果的方式\n（如逃脱按键或逃脱按键）仍然允\n许替换.");
constexpr u8 __sAbilityText_58066380[] = _("当受到火属性招式攻击或使用火属\n性招式时,将怠惰树懒变身为燃烧\n形态.无法被复制或压制.");
constexpr u8 __sAbilityText_3977801035[] = _("进入战斗时,自动使用龙之鼓舞,为\n你和你的同伴提升1级击中要害率.\n龙属性宝可梦提升2级.");
constexpr u8 __sAbilityText_3413241011[] = _("对手攻击时总是造成最小伤害,强\n制造成85%伤害而非85-100%的浮\n动.对该宝可梦的击中要害伤害仅\n为其正常伤害的25%,而非\n150-200%.");
constexpr u8 __sAbilityText_2800490534[] = _("使同伴的攻击威力提升25%,如果该\n招式是反伤招式,则提升50%.使用\n者自身不受此加成.");
constexpr u8 __sAbilityText_627238541[] = _("拥有此特性的宝可梦获得一个无法\n移除的流血状态.当使用者与另一\n只不具有此特性的宝可梦发生接触\n时（无论攻防）,会将其当前特性\n替换为此特性并造成流血.");
constexpr u8 __sAbilityText_214264895[] = _("对处于流血状态的目标造成双倍伤\n害,并且使用者免疫异常状态.");
constexpr u8 __sAbilityText_1251584126[] = _("该宝可梦每在场完成一个完整的回\n合,其速度在回合结束时提升1级.\n入场的当回合不会触发.使用攻击\n时,将使用者20%的速度能力值加入\n伤害计算.讲究围巾的效果不影响\n此特性.");
constexpr u8 __sAbilityText_680715662[] = _("出场时,赋予第一次使用的啃咬类\n招式+1优先度.在使用任何啃咬类\n招式命中后,该优先度加成即被消\n耗.通过直接攻击击倒对手后,重新\n获得优先度增益.");
constexpr u8 __sAbilityText_3096275666[] = _("移除对手宝可梦的能力提升,然后\n降低其速度1级.");
constexpr u8 __sAbilityText_1410946199[] = _("使受到的接触类招式伤害降低75%.\n火属性招式对该宝可梦造成4倍伤\n害.与其他减伤效果乘法叠加.");
constexpr u8 __sAbilityText_2782486512[] = _("真气弹必定命中.不受畏缩、威吓\n或惊吓的影响.拳类招式获得+1击\n中要害率,并且其原本的追加效果\n触发几率变为5倍.");
constexpr u8 __sAbilityText_2335768350[] = _("每当使用者通过直接攻击击倒对手\n时,其击中要害率提升1级.下雨天\n气时,该宝可梦的速度提升50%.");
constexpr u8 __sAbilityText_516223577[] = _("铁拳 + 30%钢属性伤害.");
constexpr u8 __sAbilityText_76991440[] = _("受到的火属性招式伤害减半.免疫\n灼伤伤害以及灼伤状态带来的攻击\n力降低效果.接触类招式将20%的防\n御加入攻击计算.防止麻痹状态,并\n在陷入麻痹时立即治愈.");
constexpr u8 __sAbilityText_1866861888[] = _("使脉冲、波导、波动和光环类招式\n威力提升30%.击倒对手时,立即从\n休息状态中恢复,允许立即使用破\n坏光线等招式而无需等待.");
constexpr u8 __sAbilityText_2343792333[] = _("允许所有接触类招式穿透保护类招\n式,并忽略与其相关的任何附加效\n果效果绝佳的攻击招式必定命中,\n并且必定造成击中要害.");
constexpr u8 __sAbilityText_3600146079[] = _("当该宝可梦替换上场时,为同伴回\n复其最大HP的25%.");
constexpr u8 __sAbilityText_2991289803[] = _("出场时,治愈使用者队伍中所有宝\n可梦（包括场上和后备）的异常状\n态,并为同伴回复其最大HP的25%.");
constexpr u8 __sAbilityText_2676159300[] = _("使用拳类招式造成伤害时,回复相\n当于伤害量10%的HP.");
constexpr u8 __sAbilityText_15800697[] = _("使所有翅膀、风和空气类招式的威\n力提升30%.该宝可梦免疫地面属性\n招式以及其他地面效果,如撒菱或\n场地状态,并使飞行属性招式伤害\n提升25%.");
constexpr u8 __sAbilityText_3744240061[] = _("在使用者在场时,降低所有其他宝\n可梦的防御能力值25%.多个相同的\n灾祸特性效果不叠加进行伤害计算\n时,完全无视对手的所有能力等级\n变化.");
constexpr u8 __sAbilityText_174505814[] = _("当使用者受到接触招式攻击时,迫\n使攻击者替换下场为随机同伴每次\n上场仅触发一次.");
constexpr u8 __sAbilityText_2273612290[] = _("当使用者使用接触类招式命中时,\n有30%的几率随机使目标陷入中\n毒、麻痹或流血状态.连续攻击的\n每一击都会独立判定.");
constexpr u8 __sAbilityText_2672612314[] = _("抵挡第一个命中该宝可梦的造成伤\n害的招式,之后改变形态.仅能抵挡\n非变化招式.在雾中,每次替换上场\n或当雾重新出现时,画皮会立即恢\n复.当画皮被打破时,攻击者被诅咒.");
constexpr u8 __sAbilityText_310137400[] = _("该宝可梦使用的一般和格斗属性招\n式能够以普通效果命中幽灵属性宝\n可梦.免疫威吓和惊吓.允许招式无\n视目标的特性和先天特性,包括那\n些会干扰效果或降低伤害的特性.\n无法绕过会修改基础能力值的特\n性,如草之皮毛.");
constexpr u8 __sAbilityText_2839058330[] = _("使用攻击时,将使用者20%的速度能\n力值加入伤害计算.讲究围巾的效\n果不影响此特性.");
constexpr u8 __sAbilityText_611515473[] = _("接触类招式的威力提升30%.当使用\n者通过直接攻击击倒对手时,立即\n恢复其最大HP的25%.");
constexpr u8 __sAbilityText_1784847625[] = _("每当使用者通过直接攻击击倒对手\n时,其攻击和速度能力值各提升1\n级.");
constexpr u8 __sAbilityText_3561389424[] = _("所有锐利刀刃类招式必定命中,并\n且可以穿透保护类招式,忽略与其\n相关的任何附加效果.");
constexpr u8 __sAbilityText_4132953170[] = _("替换上场时使使用者进入充电状\n态,下一次电属性招式威力加倍.在\n战斗中电气场地激活时再次充电.\n充电状态在替换下场或使用一次电\n属性招式后消失.使用电属性招式\n直接击倒对手时重新充电.");
constexpr u8 __sAbilityText_1797273319[] = _("本系招式获得20%威力提升.使用者\n在每回合开始时随机变为一种纯属\n性.");
constexpr u8 __sAbilityText_3777319664[] = _("使拳类招式攻击两次,第一击造成\n100%伤害,第二击造成40%伤害.一\n般属性招式变为虫属性并获得本系\n加成.如果使用者是虫属性,则免疫\n粉末类招式.");
constexpr u8 __sAbilityText_4158960304[] = _("当使用者在一回合中先出手时,攻\n击有20%的几率造成畏缩,并且在命\n中时束缚目标.束缚效果与畏缩是\n否成功无关.畏缩几率仅对连续攻\n击的第一击有效.");
constexpr u8 __sAbilityText_2709600410[] = _("当使用者处于任何异常状态时,其\n攻击招式威力提升50%.当该宝可梦\n受到击中要害时,其攻击和特攻各\n提升1级.同时无视灼伤带来的攻击\n降低和冰冻带来的特攻降低.");
constexpr u8 __sAbilityText_3587226939[] = _("使用者替换上场时,在对手场上设\n置一个灼伤陷阱.下一个替换上场\n的对手如果接地且可被灼伤,则会\n被灼伤.触发后陷阱消失.多个陷阱\n不会叠加.");
constexpr u8 __sAbilityText_242617311[] = _("受到的伤害降低40%,同时该宝可梦\n的速度降低20%.与其他减伤来源乘\n法叠加.");
constexpr u8 __sAbilityText_935085240[] = _("使啃咬类招式威力提升30%,并在命\n中时有50%的几率使目标麻痹.");
constexpr u8 __sAbilityText_1953837920[] = _("进入战斗时,揭示对手的物品,并使\n其效果失效2回合,同时降低所有对\n手宝可梦的特攻1级.不会阻止超级\n石及其他类似物品的运作.");
constexpr u8 __sAbilityText_788513066[] = _("替换上场时使用哈欠,以对手宝可\n梦为目标.哈欠使目标陷入瞌睡,并\n在下一回合结束时睡眠.替换下场\n可以防止睡眠.");
constexpr u8 __sAbilityText_2354196979[] = _("当其他宝可梦在战斗中使用月亮相\n关招式时,进行模仿.包括月光、月\n亮之力、月之舞和月之祝福.每回\n合对每个招式触发一次.");
constexpr u8 __sAbilityText_50332004[] = _("进入战斗时,为使用者的当前属性\n添加水属性即使失去此特性,添加\n的水属性在替换下场前依然保留.\n同时水属性招式威力提升50%.");
constexpr u8 __sAbilityText_3913741346[] = _("每回合结束时回复1/16的最大HP.\n熟成使所有树果的有益效果加倍回\n复类树果回复量加倍,提升能力的\n树果改为提升2级,抵抗树果将效果\n绝佳的伤害降低75%,回复PP的树果\n回复20 PP.");
constexpr u8 __sAbilityText_3495171049[] = _("进入战斗时,为使用者的当前属性\n添加超能力属性.即使失去此特性,\n添加的超能力属性在替换下场前依\n然保留.使用者免疫地面属性招式\n以及撒菱和场地状态等其他地面效\n果.");
constexpr u8 __sAbilityText_2436037682[] = _("对处于中毒、麻痹、流血或速度降\n低状态的目标,必定造成击中要害.\n使用者的电属性招式对电属性宝可\n梦变得有效,造成2倍伤害而非0.5\n倍.同时允许使用者使电属性宝可\n梦陷入麻痹状态.");
constexpr u8 __sAbilityText_3895907750[] = _("替换上场时使用火焰旋涡,威力50\n的火属性特殊招式,束缚对手4-5回\n合.目标每回合损失1/8最大HP,且\n在束缚结束前无法替换下场.");
constexpr u8 __sAbilityText_1367369513[] = _("替换上场时使用惊吓,威力40的幽\n灵属性物理招式,拥有+3优先度且\n必定造成畏缩每场战斗仅触发一\n次.");
constexpr u8 __sAbilityText_1094006788[] = _("替换上场时使用掷焦油,降低目标\n速度1级,并使其受到的火属性伤害\n变为2倍.后续使用不会叠加火属性\n伤害的负面效果.");
constexpr u8 __sAbilityText_724228690[] = _("当使用者攻击命中时,有60%的几率\n随机使目标陷入中毒或麻痹状态.\n连续攻击的每一击都会独立判定.");
constexpr u8 __sAbilityText_2655986624[] = _("击倒对手时,立即从休息状态中恢\n复.所有攻击连续命中两次.第一击\n造成100%伤害,第二击造成25%伤\n害.每次攻击独立判定追加效果\n（畏缩除外）.");
constexpr u8 __sAbilityText_3205003218[] = _("使用物理攻击命中时,降低目标防\n御1级.每个目标每回合只能被影响\n一次防御降低在伤害之后生效.");
constexpr u8 __sAbilityText_1829129041[] = _("该宝可梦携带的物品不会被强制移\n除或偷走.发生接触时,对手的物品\n失效2回合.");
constexpr u8 __sAbilityText_2577970116[] = _("防止使用者自身引起的能力降低,\n并允许其承受一次会使其濒死的攻\n击,留下1点HP.");
constexpr u8 __sAbilityText_1552794968[] = _("毒属性招式对钢属性宝可梦变得效\n果绝佳.此外,该宝可梦可以使任何\n属性的宝可梦陷入中毒状态.每回\n合伤害所有非毒属性宝可梦,造成\n其1/8的HP损失.拥有毒疗特性的宝\n可梦反而会回复.使用者下场时效\n果消失.");
constexpr u8 __sAbilityText_3995039901[] = _("将所有一般属性招式转变为毒属\n性,并为毒属性招式提供本系加成.\n如果使用者是毒属性,其毒属性招\n式有10%的几率造成剧毒.使使用者\n的声音类招式威力提升30%,并使受\n到的声音类招式伤害降低50%.伤害\n减免与其他来源乘法叠加.");
constexpr u8 __sAbilityText_1801102271[] = _("在使用者上场的第一回合,所有优\n先度为0或更高的招式获得+1优先\n度.负向优先度招式变为优先度0,\n而非获得+1.对刚替换上场的对手\n造成双倍伤害.仅在对手替换上场\n后的第一回合内生效.");
constexpr u8 __sAbilityText_206191490[] = _("替换上场时使用清除浓雾.降低对\n手闪避率1级,并清除所有入场陷\n阱、屏障、神秘守护和白雾.此外,\n所有空气类招式获得1.3倍伤害加\n成.");
constexpr u8 __sAbilityText_2421278586[] = _("濒死时,以威力100的火属性大爆炸\n反击所有相邻的宝可梦.必定命中.\n无论使用者如何被击倒都会生效.");
constexpr u8 __sAbilityText_2831810234[] = _("造成击中要害时施加流血.流血每\n回合造成1/16最大HP伤害,阻止回\n复,并使能力等级效果无效.岩石和\n幽灵属性免疫流血.");
constexpr u8 __sAbilityText_4062113215[] = _("使用任何舞蹈类招式后,立即触发\n一次威力50的叶刃（草属性,物\n理）作为后续攻击.");
constexpr u8 __sAbilityText_4825382[] = _("使所有非变化招式都被视为舞蹈类\n招式,可以触发舞者等特性以及与\n舞蹈相关的效果.");
constexpr u8 __sAbilityText_2453912749[] = _("当HP降至50%或以下时变身,变身完\n成后自动治愈所有异常状态.变身\n后,所有攻击都变为击中要害.在出\n场时、战斗中及回合结束时均可触\n发.");
constexpr u8 __sAbilityText_2780348887[] = _("使用接触类招式命中后,使目标在5\n回合内无论优先度、速度或其他效\n果如何,总是最后行动.效果不会叠\n加,也不会对已受影响的目标刷新.");
constexpr u8 __sAbilityText_1148151271[] = _("锐利刀刃类招式命中时有50%的几\n率造成流血.流血每回合造成1/16\n最大HP伤害,阻止回复,并使能力等\n级效果无效.岩石和幽灵属性免疫\n流血.连续攻击的每一击都会独立\n判定.");
constexpr u8 __sAbilityText_2886936446[] = _("每回合结束时,从每个在场的对手\n吸取其最大HP的1/10,并回复给使\n用者.无视替身.");
constexpr u8 __sAbilityText_665121016[] = _("从睡眠中醒来时,使用者永久获得\n睡眠免疫,且所有能力提升1级.每\n场战斗仅触发一次.");
constexpr u8 __sAbilityText_3193530787[] = _("当HP全满时,所有对该宝可梦的攻\n击都将造成效果不好的伤害,无论\n属性相性如何.与其他类似特性不\n同,此效果在连续攻击的每次命中\n都会激活.出场时清除普通天气和\n场地.");
constexpr u8 __sAbilityText_3559643366[] = _("当使用者施加灼伤时,也同时施加\n恐惧.恐惧束缚目标2回合,使其受\n到的伤害增加50%.如果被吹飞等招\n式强制替换,目标会摆脱恐惧.");
constexpr u8 __sAbilityText_2038484237[] = _("下雨天气时,速度提升50%.在对手\n之前行动时,受到的伤害降低30%.\n当该宝可梦在回合中替换上场时也\n生效.");
constexpr u8 __sAbilityText_2139635097[] = _("拳类招式使用特攻能力值进行伤害\n计算（除非另有说明,否则仍攻击\n目标的防御）,并造成30%额外伤\n害.");
constexpr u8 __sAbilityText_3136614965[] = _("出场时,赋予第一次使用的锐利刀\n刃类招式+1优先度.在使用任何锐\n利刀刃类招式命中后,该优先度加\n成即被消耗.使用磨砺可重置此特\n性.");
constexpr u8 __sAbilityText_1406740879[] = _("出场时引发沙暴,持续8回合（携带\n光滑岩石时为12回合）.在沙暴中,\n该宝可梦最高的攻击能力值提升\n50%.同时免疫沙暴伤害.");
constexpr u8 __sAbilityText_95572574[] = _("替换上场时使用威力20的沙穴攻击\n所有对手宝可梦,束缚它们4-5回\n合,使其每回合损失1/8最大HP必定\n命中,无视命中判定.");
constexpr u8 __sAbilityText_2966649344[] = _("创造终焉大晴天,持续到使用者下\n场.具有标准晴天效果,并使所有水\n属性招式无效.此外,使用者受到地\n面属性招式攻击时,回复其最大HP\n的25%而非受到伤害.");
constexpr u8 __sAbilityText_2901904138[] = _("使用者接触时使对手灼伤.无论攻\n击方还是被攻击方均会生效.");
constexpr u8 __sAbilityText_2450063594[] = _("回复使用者对对手造成伤害的25%.\n回复在伤害造成后立即生效.最少\n回复1点HP.");
constexpr u8 __sAbilityText_2187756802[] = _("该宝可梦会吸引水属性招式,并对\n其免疫.此外,吸收水属性招式时,使\n用者最高的攻击能力值提升1级,并\n回复其最大HP的25%.");
constexpr u8 __sAbilityText_2122067686[] = _("当使对手中毒时,立即降低其攻\n击、特攻和速度各1级.");
constexpr u8 __sAbilityText_2750974236[] = _("角类招式变为特殊（造成特殊伤害\n并使用特攻能力值）,并造成30%额\n外伤害.");
constexpr u8 __sAbilityText_3854018465[] = _("使用者进入战斗时,在对手场上设\n置黏黏网.持续7回合,使任何替换\n上场的接地宝可梦速度降低1级.如\n果对手场上已有黏黏网,则无法激\n活.");
constexpr u8 __sAbilityText_1114190162[] = _("使受到的接触类招式伤害降低50%.\n火属性招式对该宝可梦造成双倍伤\n害.与其他减伤效果乘法叠加.");
constexpr u8 __sAbilityText_1461200630[] = _("受到任何火属性或飞行属性招式攻\n击时,防御和特防各提升1级.对于\n连续攻击招式,每次命中都会触发.\n能力提升效果在攻击命中后生效.\n所有攻击命中两次.第一击造成\n100%伤害,第二击造成25%伤害.每\n次攻击独立判定追加效果（畏缩除\n外）.");
constexpr u8 __sAbilityText_1227816551[] = _("使所有踢腿类招式的威力提升30%.\n一般属性招式变为妖精属性,使用\n者获得妖精属性本系加成.如果使\n用者是妖精属性,其妖精属性招式\n有10%的几率造成着迷.");
constexpr u8 __sAbilityText_2298202967[] = _("使恶属性招式威力提升35%,但会造\n成基于伤害值10%的反伤（最少1点\nHP）.反伤不会导致使用者濒死.");
constexpr u8 __sAbilityText_3663519011[] = _("会造成反伤伤害的招式威力提升\n20%.处于愤怒状态时,此加成适用\n于所有招式.防止所有来自自身招\n式或特性的反伤伤害.同时免疫因\n愤怒产生的反伤伤害无法防止撞击\n伤害或大爆炸/自爆的伤害.");
constexpr u8 __sAbilityText_987307482[] = _("受到的伤害降低20%,与其他减伤来\n源乘法叠加.免疫击中要害.受到接\n触招式攻击时,使用雷电笼进行反\n击,威力50的电属性特殊招式,束缚\n对手4-5回合.目标每回合损失1/8\n最大HP,且在束缚结束前无法替换\n下场.");
constexpr u8 __sAbilityText_2490338892[] = _("毒属性招式对钢属性宝可梦变得效\n果绝佳.此外,该宝可梦可以使任何\n属性的宝可梦陷入中毒状态.同时\n为毒属性招式提供本系加成.");
constexpr u8 __sAbilityText_3256496383[] = _("出场时在对手场上撒下两层毒菱任\n何非毒或钢属性的接地敌人替换上\n场时,都会陷入剧毒.");
constexpr u8 __sAbilityText_4126978961[] = _("使用者总是能命中目标.将所有一\n般属性招式转变为格斗属性招式,\n并为格斗属性攻击提供本系加成如\n果使用者是格斗属性,其格斗属性\n招式可以击破屏障.击倒对手时,立\n即从休息状态中恢复.");
constexpr u8 __sAbilityText_1779507820[] = _("免疫所有非攻击性的伤害来源,包\n括入场陷阱、天气伤害、异常状态\n以及反伤伤害.在大部分变化招式\n生效前,将其反弹回原使用者.被反\n弹的招式作用于原使用者.无法反\n弹已被反弹的招式.");
constexpr u8 __sAbilityText_3417380559[] = _("水属性和冰属性招式威力提升25%.\n受到的火属性招式伤害减半.与其\n他减伤来源乘法叠加.");
constexpr u8 __sAbilityText_297831306[] = _("当使用者通过直接攻击击倒对手\n时,立即恢复其最大HP的25%.移除\n一般属性对幽灵属性招式的免疫,\n允许幽灵属性攻击以1倍效果命中\n一般属性宝可梦.");
constexpr u8 __sAbilityText_2842780514[] = _("进入战斗时,降低所有对手宝可梦\n的攻击能力值1级.使用者替换上场\n后的第一回合,获得50%的速度加成\n和20%的攻击加成.");
constexpr u8 __sAbilityText_3924384497[] = _("当HP全满时,赋予声音类招式+1优\n先度.");
constexpr u8 __sAbilityText_2803377008[] = _("使所有踢腿类招式的威力提升30%.\n包括火焰球.当场上任何宝可梦使\n用舞蹈类招式后,该宝可梦会立即\n使用相同的招式每回合对每个招式\n触发一次.");
constexpr u8 __sAbilityText_2564309810[] = _("拳类招式也被视为踢腿类招式,可\n从前锋类特性中受益.踢腿类招式\n也被视为拳类招式,可从铁拳类特\n性中受益.");
constexpr u8 __sAbilityText_1871309845[] = _("格斗属性招式威力提升30%,当HP低\n于1/3时提升80%.");
constexpr u8 __sAbilityText_1496795452[] = _("当战场上任何宝可梦（包括同伴和\n对手）濒死时,该宝可梦的攻击能\n力值提升1级.");
constexpr u8 __sAbilityText_491322381[] = _("当攻击处于异常状态的对手时,造\n成1.25倍伤害并自动针对其较低的\n防御能力值.对处于中毒、麻痹、\n流血或速度降低状态的目标,必定\n造成击中要害.");
constexpr u8 __sAbilityText_2607193683[] = _("出场时,在3回合内,使用者受到的\n所有攻击都被视为效果不好.替换\n下场时效果解除.");
constexpr u8 __sAbilityText_2324878998[] = _("超能力属性招式无视属性抗性和免\n疫,无论目标属性如何,至少造成普\n通伤害.此外,所有超能力招式的追\n加效果触发几率提升40%.");
constexpr u8 __sAbilityText_1309295139[] = _("使所有招式获得1.5倍的本系加成,\n无论属性是否匹配.不会增强已经\n获得本系加成的招式.觉醒力量/自\n然之力总是效果绝佳（x2）.详细\n机制解释");
constexpr u8 __sAbilityText_2338890204[] = _("使脉冲、波导、波动和光环类招式\n威力提升30%.超级发射器类招式必\n定命中,并同时攻击双方对手.所有\n脉冲、波导、波动、光环及其他爆\n裂相关招式不会打空.");
constexpr u8 __sAbilityText_1187515651[] = _("无论攻击方还是被攻击方,使用接\n触类招式时有30%的几率使对手中\n毒.使角和钻类攻击的威力提升\n30%.");
constexpr u8 __sAbilityText_1900208605[] = _("当该宝可梦HP全满时,受到的所有\n伤害降低50%.与其他减伤来源乘法\n叠加.无论攻击方还是被攻击方,使\n用接触类招式时有30%的几率使对\n手中毒.");
constexpr u8 __sAbilityText_213531323[] = _("使脉冲、波导、波动和光环类招式\n威力提升30%.此外,所有变化招式\n都被视为超级发射器招式,可从相\n关特性中获得加成.");
constexpr u8 __sAbilityText_281512058[] = _("在使用者替换上场后的第一回合或\n战斗开始时,必定造成击中要害.使\n用者不会打空箭矢类攻击和炮类招\n式（仅限被防弹阻挡的招式）.此\n外,造成击中要害时,攻击目标改为\n对手较弱的防御能力值.");
constexpr u8 __sAbilityText_551196068[] = _("当使用者使宝可梦中毒时,中毒的\n目标被清除所有能力提升,并且无\n法通过任何方式回复HP.");
constexpr u8 __sAbilityText_3204342363[] = _("在双打对战中,每回合结束时,有\n30%的几率治愈自身和场上同伴的\n异常状态.对两只宝可梦分别进行\n几率判定在双打对战中,该宝可梦\n的同伴受到的伤害降低50%.与其他\n减伤来源乘法叠加.");
constexpr u8 __sAbilityText_3220472237[] = _("替换上场时使用潮旋,威力50的水\n属性特殊招式,束缚对手4-5回合.\n目标每回合损失1/8最大HP,且在束\n缚结束前无法替换下场.");
constexpr u8 __sAbilityText_132098951[] = _("每回合结束时自动在吃饱形态和饥\n饿形态之间切换.电属性和恶属性\n招式威力提升35%,但会造成基于伤\n害值10%的反伤（最少1点HP）.反\n伤不会导致使用者濒死.无法以任\n何方式覆盖、压制、交换或复制.");
constexpr u8 __sAbilityText_1446774529[] = _("将唱歌的命中率提升至90%.不锁定\n为90%,该招式仍会受到命中率/闪\n避率变化的影响.");
constexpr u8 __sAbilityText_2615034661[] = _("受到水属性攻击时,攻击提升1级,\n并在下一回合防御提升1级.受到冰\n属性攻击时,当回合攻击和防御各\n提升1级.对于连续攻击招式,每次\n命中都会触发.");
constexpr u8 __sAbilityText_1492670734[] = _("使用冰属性招式后,使用者紧接着\n使用威力50的暴风雪（冰属性,85%\n命中率,攻击双方,20%冻伤几率,基\n于天气）.");
constexpr u8 __sAbilityText_493512222[] = _("免疫所有非攻击性的伤害来源,包\n括入场陷阱、天气伤害、异常状态\n以及反伤伤害.当HP全满时,该宝可\n梦能够承受任何一次攻击并至少留\n下1点HP.");
constexpr u8 __sAbilityText_3668926288[] = _("所有攻击连续命中两次.第一击造\n成100%伤害,第二击造成25%伤害.\n每次攻击独立判定追加效果（畏缩\n除外）.阻止所有不具有影子游戏\n特性或非幽灵属性的对手替换下\n场.伏特替换等替换招式仍允许他\n们替换.");
constexpr u8 __sAbilityText_1985674323[] = _("根据使用的招式改变代欧奇希斯的\n形态.攻击招式触发攻击形态,自我\n再生触发防御形态,其他变化招式\n触发速度形态.形态变化在攻击前\n发生.");
constexpr u8 __sAbilityText_985679476[] = _("进入战斗时,为使用者的当前属性\n添加钢属性.即使失去此特性,添加\n的钢属性在替换下场前依然保留.\n所有啃咬类招式攻击两次.第一击\n造成100%伤害,第二击造成40%伤\n害.每次攻击独立判定追加效果\n（畏缩除外）.");
constexpr u8 __sAbilityText_1920165611[] = _("当该宝可梦在目标之后行动时,攻\n击威力提升30%.效果绝佳的攻击威\n力提升35%.");
constexpr u8 __sAbilityText_2240016110[] = _("总是能对对手命中效果绝佳的攻\n击.允许效果绝佳的攻击无视目标\n的特性和先天特性,包括那些会干\n扰效果或降低伤害的特性.");
constexpr u8 __sAbilityText_2027899560[] = _("替换上场时,该宝可梦的速度能力\n值提升1级.");
constexpr u8 __sAbilityText_1281489185[] = _("替换上场时,该宝可梦的攻击能力\n值提升1级.");
constexpr u8 __sAbilityText_824839664[] = _("替换上场时,该宝可梦的防御能力\n值提升1级.");
constexpr u8 __sAbilityText_3949692058[] = _("替换上场时,该宝可梦的特防能力\n值提升1级.");
constexpr u8 __sAbilityText_3479371494[] = _("岩石属性招式威力提升30%,当HP低\n于1/3时提升80%.");
constexpr u8 __sAbilityText_3477318208[] = _("将使用者的一般属性招式变为恶属\n性.如果使用者是恶属性,其恶属性\n招式有10%的几率造成愤怒；否则,\n它获得恶属性的本系加成.");
constexpr u8 __sAbilityText_3963414116[] = _("在大晴天下,每回合结束时治愈所\n有异常状态,并且每回合结束时有\n50%几率回收树果,大晴天下为\n100%.包括用于投掷、自然之恩或\n被吃掉的树果.");
constexpr u8 __sAbilityText_1347630027[] = _("大晴天激活时,使用者的速度和最\n高的攻击能力值提升50%.");
constexpr u8 __sAbilityText_268649677[] = _("对火属性宝可梦造成1.5倍伤害,并\n且受到火属性宝可梦攻击时,伤害\n减半.此效果基于攻击方/防御方宝\n可梦的属性,而非招式属性.伤害减\n免与其他来源乘法叠加.");
constexpr u8 __sAbilityText_2518404034[] = _("结合有色眼镜和沙之守卫.攻击被\n抵抗时造成双倍伤害.在沙暴中,阻\n挡对手的先制招式,并使受到的特\n殊攻击伤害减半.同时像其他地面\n属性一样免疫沙暴伤害.");
constexpr u8 __sAbilityText_2992673214[] = _("击中要害时的伤害倍率从1.5倍提\n升至2.25倍,即额外增加50%的伤害\n加成.在对手替换下场前以50%的威\n力攻击他们,在其离开前造成伤害.");
constexpr u8 __sAbilityText_4023826499[] = _("进入战斗时,对随机一名对手使用\n森林诅咒,为其添加草属性.当对手\n与使用者发生接触时,他们也会被\n添加草属性作为额外属性.仅影响\n非草属性目标.效果持续到替换下\n场.");
constexpr u8 __sAbilityText_3119284265[] = _("受到接触招式攻击时,使用者压制\n攻击者的特性和先天特性,直到他\n们替换下场.");
constexpr u8 __sAbilityText_1427430151[] = _("当受到接触招式攻击时,该宝可梦\n使用其速度能力值而非防御或特防\n进行伤害计算.讲究围巾的效果不\n影响此特性.");
constexpr u8 __sAbilityText_232275871[] = _("受特殊招式攻击时，用速度而非防\n御或特防计算伤害。讲究围巾不影\n响此特性。");
constexpr u8 __sAbilityText_448206323[] = _("攻击被抵抗时,伤害加倍.如果招式\n被抵抗（0.5倍伤害或更低）,则最\n终伤害乘以2倍.当使用者通过直接\n攻击击倒对手时,立即从休息状态\n中恢复.");
constexpr u8 __sAbilityText_2796500667[] = _("将所有一般属性招式转变为声音类\n招式,使其能够受益于基于声音的\n特性和互动.");
constexpr u8 __sAbilityText_2811808760[] = _("将所有一般属性招式转变为铁拳和\n前锋类招式,使其能够受益于相关\n特性和互动.");
constexpr u8 __sAbilityText_2729009278[] = _("当使用者后手攻击时,击中要害率\n提升2级,攻击威力提升30%.");
constexpr u8 __sAbilityText_3229001917[] = _("当该宝可梦的招式造成击中要害\n时,它们会无视通常会降低伤害的\n防御性特性,并且如果招式被抵抗,\n则造成双倍伤害.对于连续攻击招\n式,如果第一击是击中要害,则所有\n攻击都无视特性,否则都不无视.");
constexpr u8 __sAbilityText_2293942173[] = _("当它陷入混乱时,对其他宝可梦施\n加特性压制.压制效果在这些宝可\n梦在场期间持续.拥有精神污染特\n性的宝可梦不受影响.");
constexpr u8 __sAbilityText_3123293617[] = _("进入迷雾时陷入愤怒.当使用者愤\n怒时,所有受到的伤害降低50%,且\n不会受到愤怒伤害.");
constexpr u8 __sAbilityText_3264667539[] = _("束缚类招式持续6回合而非4-5回\n合,并且每回合结束时的伤害提升\n至目标最大HP的1/6.攻击有50%几\n率束缚目标6回合,防止逃跑或替\n换.一旦被束缚,目标每在场一回合\n速度降低1级.");
constexpr u8 __sAbilityText_3450393353[] = _("攻击有50%几率束缚目标4-5回合,\n防止逃跑或替换.一旦被束缚,目标\n每在场一回合速度降低1级.");
constexpr u8 __sAbilityText_3940155838[] = _("在迷雾激活时,每回合结束时,从每\n个在场的对手吸取其最大HP的\n1/10,并回复给使用者.无视替身.");
constexpr u8 __sAbilityText_1292303026[] = _("进入战斗时,降低所有对手宝可梦\n的特攻1级对手无法造成击中要害,\n总是造成最低伤害（85%而非\n85-100%）,无法触发非必定触发的\n追加效果,并且有5%的几率招式落\n空.");
constexpr u8 __sAbilityText_481499547[] = _("进入战斗时,为使用者的当前属性\n添加幽灵属性.即使失去此特性,添\n加的幽灵属性在替换下场前依然保\n留.当HP全满时,所有受到的攻击伤\n害减半.与其他减伤来源乘法叠加.");
constexpr u8 __sAbilityText_3335679134[] = _("出场时使用威力10的冰息（冰属\n性,特殊,空气类）,攻击所有对手并\n降低其速度1级.");
constexpr u8 __sAbilityText_1785714334[] = _("当造成冻伤时,使用者也会施加封\n印.封印阻止目标使用其最后使用\n的招式,持续4回合.如果目标尚未\n行动,则失败.");
constexpr u8 __sAbilityText_1493915939[] = _("在冰雹中,该宝可梦的速度提升\n50%,并且对手的命中率降低25%.免\n疫冰雹伤害.");
constexpr u8 __sAbilityText_3663873020[] = _("受到接触招式攻击时,有50%几率使\n攻击者着迷（将其攻击和特攻减\n半）.同时为妖精属性招式提供本\n系加成.");
constexpr u8 __sAbilityText_48482833[] = _("每回合结束时,该宝可梦有30%的几\n率治愈自身所受到的异常状态.免\n疫对手所有提升伤害的特性效果,\n亲子爱和多头龙特性除外.");
constexpr u8 __sAbilityText_1899896410[] = _("不会实装.");
constexpr u8 __sAbilityText_3302772529[] = _("使用者无视大多数增加伤害或额外\n攻击次数的特性.将使用者的一般\n属性招式变为钢属性.如果使用者\n是钢属性,它抵抗幽灵和钢属性；\n否则,它获得钢属性的本系加成.");
constexpr u8 __sAbilityText_645517671[] = _("时光咆哮变为威力100,优先度0的\n攻击,将目标的特性变为慢启动\n（攻击、特攻和速度减半5回合）,\n但不再强制目标替换.");
constexpr u8 __sAbilityText_3386241798[] = _("声音类招式命中时造成恐惧.恐惧\n束缚目标2回合,使其受到的伤害增\n加50%.如果被吹飞等招式强制替\n换,目标会摆脱恐惧.");
constexpr u8 __sAbilityText_1050262556[] = _("当使用者成功使对手中毒时,压制\n对手的特性和先天特性.压制效果\n在他们替换下场后解除.");
constexpr u8 __sAbilityText_3525644118[] = _("设置顺风时也会设置青草场地,设\n置青草场地时也会设置顺风.如果\n其中一种效果已激活,则不会刷新\n其持续时间.");
constexpr u8 __sAbilityText_132680240[] = _("替换上场时设置剧毒场地,持续8回\n合（携带场地制造机时为12回合\n）.激活时,非毒或钢属性的接地宝\n可梦每回合损失1/16最大HP,毒属\n性招式威力提升30%,撒菱会转变为\n毒菱.");
constexpr u8 __sAbilityText_1162251862[] = _("进入战斗时,为使用者的当前属性\n添加水属性即使失去此特性,添加\n的水属性在替换下场前依然保留.\n同时水属性招式威力提升50%.下雨\n天气时,速度提升50%.");
constexpr u8 __sAbilityText_1224597054[] = _("在剧毒场地中,使用者的特防能力\n值提升50%.");
constexpr u8 __sAbilityText_3604385058[] = _("当使用者束缚目标时,它们造成麻\n痹,并且在被束缚期间每回合降低\n其速度1级.");
constexpr u8 __sAbilityText_3048074392[] = _("免疫沙暴和冰雹的天气伤害,并阻\n挡所有粉末类招式,包括催眠粉、\n麻痹粉、毒粉、蘑菇孢子、棉孢\n子、愤怒粉、粉末和魔法粉.同时,\n受到的物理伤害降低20%.与其他减\n伤来源乘法叠加.");
constexpr u8 __sAbilityText_4149025014[] = _("替换上场时使用清除浓雾,清除所\n有入场陷阱、屏障、神秘守护和白\n雾.同时降低对手的闪避率1级.");
constexpr u8 __sAbilityText_2981689730[] = _("对使用接触类招式的攻击者造成其\n最大HP1/8的伤害.同时,无论攻击\n方还是被攻击方,使用接触类招式\n时有30%的几率使对手中毒.对于连\n续攻击招式,每次命中都会触发.");
constexpr u8 __sAbilityText_186462743[] = _("将所有一般属性招式转变为龙属性\n招式,并为龙属性招式提供本系加\n成.如果使用者是龙属性,其龙属性\n招式对妖精属性造成普通伤害.出\n场时,为使用者的当前属性添加龙\n属性即使失去此特性,添加的龙属\n性在替换下场前依然保留.");
constexpr u8 __sAbilityText_400147569[] = _("声音类招式也被视为舞蹈类招式,\n可从舞者类特性中受益.舞蹈类招\n式也被视为声音类招式,可从基于\n声音的特性中受益.");
constexpr u8 __sAbilityText_347799365[] = _("进入战斗时,为使用者的当前属性\n添加妖精属性.即使失去此特性,添\n加的妖精属性在替换下场前依然保\n留.使用者免疫地面属性招式以及\n其他地面效果,如撒菱和场地状态.\n飞行属性招式伤害提升25%.");
constexpr u8 __sAbilityText_3983806040[] = _("锐利刀刃类招式变为特殊（造成特\n殊伤害并使用特攻能力值）,并在\n攻击计算中使用使用者20%的特防\n能力值.");
constexpr u8 __sAbilityText_2169213287[] = _("使角和钻类攻击的威力提升30%,并\n且有30%的几率使目标流血流血每\n回合造成1/16最大HP伤害,阻止回\n复,并使能力等级效果无效.岩石和\n幽灵属性免疫流血.");
constexpr u8 __sAbilityText_3101601570[] = _("锐利刀刃类招式变为特殊（造成特\n殊伤害并使用特攻能力值）,并在\n攻击计算中使用使用者20%的特防\n能力值.同时,锐利刀刃类招式攻击\n两次,每次造成招式正常伤害的\n70%.追加效果在每次攻击中独立判\n定（畏缩除外）.");
constexpr u8 __sAbilityText_1876901732[] = _("进入战斗时,为使用者的当前属性\n添加电属性即使失去此特性,添加\n的电属性在替换下场前依然保留.");
constexpr u8 __sAbilityText_2636722736[] = _("当陷入畏缩状态时,速度提升1级.\n防止因招式或红牌被强制替换.");
constexpr u8 __sAbilityText_814489974[] = _("物理非接触类招式造成20%额外伤\n害.接触类招式有50%几率束缚目标\n4-5回合.");
constexpr u8 __sAbilityText_3311718411[] = _("自身招式的追加效果触发几率加\n倍.使所有翅膀、风和空气类招式\n的威力提升30%.");
constexpr u8 __sAbilityText_2605550411[] = _("进入战斗时,为使用者的当前属性\n添加龙属性.即使失去此特性,添加\n的龙属性在替换下场前依然保留.\n使用者在使用任何招式命中后,有\n30%的几率使目标陷入剧毒连续攻\n击的每一击都会独立判定.");
constexpr u8 __sAbilityText_2042134075[] = _("使用者在使用任何招式命中后,有\n30%的几率使目标中毒.连续攻击的\n每一击都会独立判定.");
constexpr u8 __sAbilityText_3165368741[] = _("使用招式后,紧接着使用威力20的\n毒瓦斯（毒属性,特殊,20%几率中\n毒,对飞行属性效果绝佳）.");
constexpr u8 __sAbilityText_3106490117[] = _("使脉冲、波导、波动和光环类招式\n威力提升30%.啃咬类招式使用特攻\n能力值进行伤害计算（除非另有说\n明,否则仍攻击目标的防御）,并造\n成30%额外伤害.");
constexpr u8 __sAbilityText_239913665[] = _("防止使用者和它的同伴成为优先度\n大于0的先制招式的目标.出场时使\n用大蛇瞪眼,使目标麻痹.每场战斗\n仅触发一次.");
constexpr u8 __sAbilityText_461349922[] = _("当该宝可梦通过直接攻击使对手濒\n死时,其速度能力值提升1级.");
constexpr u8 __sAbilityText_3753701875[] = _("该宝可梦在招式和状态判定中被视\n为处于睡眠状态.可以正常行动,并\n且免疫所有异常状态.当场上任何\n宝可梦处于睡眠时,招式威力加倍.\n攻击会对正在替换下场的睡眠中对\n手造成1倍伤害,在其离开前造成伤\n害.伤害提升20%.");
constexpr u8 __sAbilityText_195336096[] = _("如果该宝可梦本回合还未行动,则\n受到的伤害降低30%.与其他减伤来\n源乘法叠加.当该宝可梦在回合中\n替换上场时也生效.如果目标本回\n合已行动,则造成的伤害提升30%.");
constexpr u8 __sAbilityText_2498424785[] = _("使啃咬和颚类招式威力提升30%.使\n用啃咬类招式击败对手时,回复50%\n最大HP；使用其他招式击败时,回\n复25%.仅当通过直接攻击击倒目标\n时触发.");
constexpr u8 __sAbilityText_942859393[] = _("在冰雹或大晴天下,该宝可梦的速\n度提升50%.同时免疫冰雹伤害.");
constexpr u8 __sAbilityText_1208468265[] = _("将所有招式的灼伤或冻伤几率乘以\n5倍.与火焰之躯或冻结点特性不叠\n加.");
constexpr u8 __sAbilityText_924656976[] = _("每次上场,在受到接触招式攻击时,\n获得50%伤害减免并强制替换攻击\n者.与其他减伤来源乘法叠加.");
constexpr u8 __sAbilityText_641130323[] = _("吸引火属性招式并对其免疫.此外,\n受到火属性招式攻击后,自身最高\n的攻击能力值提升1级.");
constexpr u8 __sAbilityText_860560439[] = _("在使用者在场时,所有其他宝可梦\n无法从属性或特性中获得本系加\n成.");
constexpr u8 __sAbilityText_367922664[] = _("出场时降下雨水并制造电气场地,\n持续8回合（携带潮湿岩石/场地制\n造机时为12回合）.水属性招式威\n力提升50%,火属性伤害降低50%.地\n面上的宝可梦不会陷入睡眠,且电\n属性招式威力提升30%.");
constexpr u8 __sAbilityText_2910836209[] = _("吸收电属性招式以免疫,并提升较\n高的攻击能力值1级.比较攻击与特\n攻以决定提升目标非常适合在对抗\n电属性攻击时进行强化,同时提供\n防御免疫和进攻增益.");
constexpr u8 __sAbilityText_392168305[] = _("创造终焉大晴天,持续到使用者下\n场.使所有造成伤害的水属性招式\n无效.火属性招式获得50%威力提\n升.除其他原始天气外,无法被覆盖.\n激活与大晴天相关招式的额外效\n果.出场时设置3回合的顺风.使所\n有同伴速度加倍.");
constexpr u8 __sAbilityText_3352530934[] = _("受到岩石属性招式攻击或在有隐形\n岩的情况下替换上场时,速度提升2\n级.同时,吸收任何岩石属性招式或\n隐形岩伤害,并回复其最大HP的\n25%.");
constexpr u8 __sAbilityText_2851747572[] = _("使用者免疫火属性招式,并在受到\n火属性招式攻击时回复其最大HP的\n25%.能够触发灼伤的招式使用时必\n定造成灼伤.");
constexpr u8 __sAbilityText_978744839[] = _("使用者的特攻能力值提升50%.与其\n他伤害加成效果乘法叠加.出场时\n设置极光幕,使同伴受到的物理和\n特殊伤害减半.持续5回合,携带光\n之黏土时为8回合.免疫冰雹伤害.");
constexpr u8 __sAbilityText_3260510432[] = _("所有非冰属性宝可梦每回合结束时\n损失1/8的最大HP.每回合结束时为\n冰属性宝可梦回复1/8的最大HP.");
constexpr u8 __sAbilityText_2030077522[] = _("回复使用者对对手造成伤害的1/8.\n回复在伤害造成后立即生效.最少\n回复1点HP.");
constexpr u8 __sAbilityText_702599831[] = _("每回合结束时随机吃一个以下树\n果：利木果、文柚果、枝荔果、龙\n晴果、沙鳞果、龙火果、杏仔果、\n兰萨果、星桃果、嘉珍果或随机一\n个危机回复树果.");
constexpr u8 __sAbilityText_4183289021[] = _("在沙暴激活时,所有同伴免疫异常\n状态和来自敌人招式的追加效果.\n每回合结束时回复该宝可梦1/16的\n最大HP.");
constexpr u8 __sAbilityText_3218042154[] = _("每当使用者通过直接攻击击倒对手\n时,其特攻能力值提升1级.根据头\n数,每次攻击2-3次.2头总倍率1.25\n倍,3头总倍率1.35倍.");
constexpr u8 __sAbilityText_2474869529[] = _("使用接触类招式命中后,使目标在5\n回合内无论优先度、速度或其他效\n果如何,总是最后行动.效果不会叠\n加,也不会对已受影响的目标刷新.\n束缚类招式持续6回合而非4-5回\n合,并且每回合结束时的伤害提升\n至目标最大HP的1/6.");
constexpr u8 __sAbilityText_3253461143[] = _("出场时随机设置青草或精神场地,\n几率各50%.携带青草种子必定触发\n青草场地,携带精神种子必定触发\n精神场地.");
constexpr u8 __sAbilityText_760995996[] = _("当使用者或其同伴的能力被降低\n时,提升攻击和防御.受到效果绝佳\n的招式攻击时,伤害降低35%.与其\n他减伤来源乘法叠加.");
constexpr u8 __sAbilityText_1224424515[] = _("无论攻击方还是被攻击方,发生接\n触时有50%几率束缚对手,效果类似\n于夹住.如果使用者本回合刚替换\n上场或通过超级进化等方式获得此\n特性,则几率提升至100%.");
constexpr u8 __sAbilityText_2159026243[] = _("使用者的冰属性招式对目标施加冰\n雕状态,使其变为冰属性,失去所有\n抗性和冻伤免疫.如果施加了冰雕\n状态,使用者会替换下场.");
constexpr u8 __sAbilityText_1308175247[] = _("受到的所有攻击伤害降低10%.被抵\n抗时降低20%.");
constexpr u8 __sAbilityText_3840856378[] = _("第一次电属性攻击威力提升2倍,之\n后失去电属性.");
constexpr u8 __sAbilityText_1314655653[] = _("使用反伤招式后,攻击+1.反伤伤害\n减半.");
constexpr u8 __sAbilityText_2032290938[] = _("锐利刀刃类招式造成1.3倍伤害,变\n为特殊招式,使用特攻能力值并攻\n击特防.同时降低目标特防1级（每\n回合每个目标最多一次）.");
constexpr u8 __sAbilityText_1378810156[] = _("出场时防御提升至+6级.受到攻击\n后防御降低1级.连续攻击会多次降\n低防御.");
constexpr u8 __sAbilityText_2645146807[] = _("出场时降低所有对手的特攻2级将\n使用者的一般属性招式变为恶属\n性.如果使用者是恶属性,其恶属性\n招式有10%的几率造成愤怒；否则,\n它获得恶属性的本系加成.");
constexpr u8 __sAbilityText_1231703724[] = _("受到冰雹影响时特防提升50%。\n此提升适用于所有\n依赖防御的效果。");
constexpr u8 __sAbilityText_177547545[] = _("丛林热在青草场地激活时,该宝可\n梦的速度能力值提升50%.场地开始\n时立即生效,场地结束时加成消失.");
constexpr u8 __sAbilityText_239057912[] = _("出场时创造青草场地，\n持续8回合(携带大地膜为12回合\n)。\n自身招式可穿透光墙、\n神秘守护、白雾与替身。");
constexpr u8 __sAbilityText_1654871487[] = _("自己的一般属性招\n式变为虫属性。\n如果自己是虫属性则\n免疫粉末类招式，\n否则获得虫属性本系加成。\n所有翼、风、\n空气类招式的威力提升30%。");
constexpr u8 __sAbilityText_89181507[] = _("接触类招式计算时\n额外加入自身20%防御。\n免疫麻痹,若已麻痹则立即治愈。\n出场时召唤沙暴,持续8回合\n(携带沙沙岩石为12回合)。\n免疫沙暴伤害。");
constexpr u8 __sAbilityText_3696019393[] = _("所有攻击连续命中两次:\n第一次100%,第二次50%。\n每次命中独立判定追加效果\n(畏缩除外)。\n可无视坚壁/奇迹皮肤。");
constexpr u8 __sAbilityText_2296456248[] = _("自身使用的招式\n视同处于强烈阳光下。\n出场时创造青草场地,持续8回合\n(携带大地膜为12回合)。");
constexpr u8 __sAbilityText_4257890142[] = _("免疫异常状态。\n受到毒属性招式和接触\n类招式的伤害减半，\n但受到水属性招\n式的伤害翻倍。");
constexpr u8 __sAbilityText_1685760165[] = _("当自己受到任何伤\n害招式攻击时，\n攻击方会陷入灼伤。");
constexpr u8 __sAbilityText_216884599[] = _("接触类招式有30%\n几率使对手流血，\n攻击和被攻击时均有效。\n角类和钻类招式\n的威力提升30%。");
constexpr u8 __sAbilityText_2365372517[] = _("超能力场地激活时，自己\n的物理招式伤害提升30%。\n即使自己不接地也有效。");
constexpr u8 __sAbilityText_3395379135[] = _("当自己成功使对手流血时，\n无效化对手的特性和天赋。\n压制效果在对手替\n换下场后消失。");
constexpr u8 __sAbilityText_3466776456[] = _("自己的电属性招式对\n地面属性造成效果不\n佳的伤害而非无效，\n对电属性造成效果绝佳\n的伤害而非效果不佳。\n自己可以使电属性麻痹。");
constexpr u8 __sAbilityText_2802606852[] = _("上场时为此宝可梦追加\n恶属性。即使失去此特\n性也保留恶属性，\n仅在替换下场时消失。");
constexpr u8 __sAbilityText_1032911834[] = _("上场时为此宝可梦追加\n火属性。即使失去此特\n性也保留火属性，\n仅在替换下场时消失。");
constexpr u8 __sAbilityText_3202639996[] = _("上场时为此宝可梦\n追加超能力属性。\n即使失去此特性也\n保留超能力属性，\n仅在替换下场时消失。");
constexpr u8 __sAbilityText_2498683146[] = _("上场时为此宝可梦\n追加飞行属性。\n即使失去此特性也\n保留飞行属性，\n仅在替换下场时消失。");
constexpr u8 __sAbilityText_2143476084[] = _("对虫属性宝可梦造成1.5\n倍伤害，被虫属性宝可梦\n攻击时受到的伤害减半。\n基于攻击方与防守方的宝\n可梦属性，而非招式属性。\n减伤与其他来源乘算。");
constexpr u8 __sAbilityText_2873525220[] = _("上场时为此宝可\n梦追加虫属性。\n即使失去此特性\n也保留虫属性，\n仅在替换下场时消失。");
constexpr u8 __sAbilityText_2665989735[] = _("此宝可梦可以灼伤火属性宝可梦，\n无视灼伤免疫。\n火属性招式无视对手干扰\n效果或减伤的特性和天赋。");
constexpr u8 __sAbilityText_3145387472[] = _("上场时自动对对手\n施加黑色目光。\n黑色目光使对手\n无法替换下场。");
constexpr u8 __sAbilityText_1521492087[] = _("冰属性招式的威力提升20%，\nHP低于1/3时提升50%。");
constexpr u8 __sAbilityText_4211937685[] = _("毒属性招式的威力提升20%，\nHP低于1/3时提升50%。");
constexpr u8 __sAbilityText_910224701[] = _("受到冰属性招式攻击时，\n免疫冰属性招式并\n使防御提升2级。");
constexpr u8 __sAbilityText_3503306481[] = _("HP全满时，\n草属性招式获得先制+1。");
constexpr u8 __sAbilityText_4211327528[] = _("上场时为此宝可梦追加草属性。即\n使失去此特性也保留草属性，仅在\n替换下场时消失。");
constexpr u8 __sAbilityText_1342034179[] = _("电气场地激活时，\n电属性招式威力提升50%。");
constexpr u8 __sAbilityText_2914905202[] = _("自身电属性招式对地面属性宝可梦\n造成效果绝佳的伤害，而非无效。");
constexpr u8 __sAbilityText_3737732606[] = _("自身变化招式必定命中，\n无论命中与闪避等级如何。");
constexpr u8 __sAbilityText_657502477[] = _("自身水属性招式的伤害翻倍。");
constexpr u8 __sAbilityText_4069857814[] = _("自身格斗属性招式的伤害翻倍。");
constexpr u8 __sAbilityText_3643801479[] = _("拳击与踢击招式伤害提升50%，\n与铁拳、踢击效果叠加。");
constexpr u8 __sAbilityText_3855244102[] = _("自身使用的所有招式都视为骨系招\n式，\n因此骨之领域等特性对全部招式生\n效。");
constexpr u8 __sAbilityText_2230344039[] = _("自身击中要害时，\n造成等于目标剩余HP的伤害。\n结实、气势披带与挺住仍可撑住。");
constexpr u8 __sAbilityText_248302053[] = _("自身所有音波招式必定击中要害，\n除非目标免疫要害\n(战斗盔甲、贝壳盔甲等)。");
